local dialogues = {}
dialogues.npcs = {
    ["Qaseem"] = {
        ["I don't feel comfortable helping you try on shoes when you are wielding something. Please remove what you are holding first."] = "No me siento cómodo ayudándote a probarte zapatos cuando estás empuñando algo. Primero retire lo que tiene en sus manos.",
        ["You'll have to take what you're wearing on your feet off first."] = "Primero tendrás que quitarte lo que llevas puesto.",
        ["You will need to remove anything worn on your feet and also disable any feet overrides before you can change your shoes."] = "Deberá quitarse todo lo que lleve puesto en los pies y también desactivar las anulaciones de los pies antes de poder cambiarse los zapatos.",
        ["Dialogue 1"] = "Diálogo 1",
        ["Good call!"] = "¡Buena decisión!",
        ["Dialogue 2"] = "Diálogo 2",
        ["Hey, they look great!"] = "¡Oye, se ven geniales!",
        ["Dialogue 3"] = "Diálogo 3",
        ["I think they suit you."] = "Creo que te quedan bien.",
        ["Dialogue 4"] = "Diálogo 4",
        ["Nice choice!"] = "¡Buena elección!",
        ["Thanks."] = "Gracias.",
    },
    ["Qat"] = {
        ["Meow, meow meow."] = "Miau, miau, miau.",
        ["Ooh, aren’t you an odd looking cat!"] = "Oh, ¿no eres un gato de aspecto extraño?",
        ["I’m not a cat."] = "No soy un gato.",
        ["But you’re talking cat, so you must be a cat. I may be old, but I ain’t slow yet."] = "Pero estás hablando de un gato, así que debes ser un gato. Puede que sea viejo, pero todavía no soy lento.",
        ["Now, I imagine a cat like you doesn’t get much attention in the romantic way. So I’m betting you’re single. Now, don’t fret, I have some lovely grandchildren that I’m sure you’d love."] = "Ahora, imagino que un gato como tú no recibe mucha atención en el sentido romántico. Así que apuesto a que estás soltero. Ahora, no te preocupes, tengo unos nietos encantadores que estoy seguro te encantarán.",
        ["They’re not much to look at. Their father was the ugliest tomcat I ever did see, but they’ve got good hearts and excellent hunting skills."] = "No hay mucho que ver. Su padre era el gato más feo que he visto en mi vida, pero tienen buen corazón y excelentes habilidades de caza.",
        ["I’ll pass, thanks."] = "Pasaré, gracias.",
        ["Pfft, suit yerself."] = "Pfft, haz lo que quieras.",
    },
    ["Quarry overseer"] = {
        ["*When selecting \"Talk to\" with the Quarry overseer in Ashdale, he will produce one of the following overhead dialogue at random, accompanied by a matching voice-over.*"] = "*Al seleccionar \"Hablar con\" con Quarry overseer en Ashdale, producirá uno de los siguientes diálogos generales al azar, acompañado de una voz en off correspondiente.*",
    },
    ["Quartermaster (Cabbage Facepunch Bonanza)"] = {
        ["Select an Option"] = "Selecciona una opción",
        ["What's going on here?"] = "¿Qué está pasando aquí?",
        ["Well, the short version is that the gods Marimbo and Brassica Prime, and the Godless, had a big contest fight-party near Lumbridge. They're gone now, but the dungeon they created is still around."] = "Bueno, la versión corta es que los dioses Marimbo y Brassica Prime, y los Godless, tuvieron una gran pelea de competencia cerca de Lumbridge. Ya no están, pero la mazmorra que crearon todavía existe.",
        ["You can take this tunnel there and pick up trophies while avoiding traps and guards, and earn rewards for it."] = "Puedes llevar este túnel hasta allí y recoger trofeos mientras evitas trampas y guardias, y ganar recompensas por ello.",
        ["What's the long version?"] = "¿Cuál es la versión larga?",
        ["Well, it seems that Marimbo and Brassica Prime saw the recent fighting between the other gods and decided to join in."] = "Bueno, parece que Marimbo y Brassica Prime vieron la reciente pelea entre los otros dioses y decidieron unirse.",
        ["I don't think they quite saw it as a fight, though. Marimbo knocked back banana daiquiris like it was going out of style, and Brassica Prime was acting like it was some sort of popularity contest."] = "Aunque no creo que lo vieran como una pelea. Marimbo bebió daiquiris de plátano como si estuviera pasando de moda, y Brassica Prime actuaba como si fuera una especie de concurso de popularidad.",
        ["The Godless were in on it too - Holstein and Kara-Meir, although it didn't work out well for her - but they couldn't stop Brassica winning the 'fight'."] = "Los Godless también estuvieron involucrados, Holstein y Kara-Meir, aunque no funcionó bien para ella, pero no pudieron evitar que Brassica ganara la 'pelea'.",
        ["The two gods said something I didn't quite catch, and that big stone plinth just sank into the ground. Now there's a doorway there. Never knew there was a dungeon under these fields."] = "Los dos dioses dijeron algo que no entendí del todo, y ese gran pedestal de piedra simplemente se hundió en el suelo. Ahora hay una puerta allí. Nunca supe que había una mazmorra debajo de estos campos.",
        ["And it's crazy in there! The walls move around and there's fire and monkeys and cabbages and..."] = "¡Y es una locura ahí dentro! Las paredes se mueven y hay fuego y monos y coles y...",
        ["The farmer takes a deep breath."] = "El granjero respira profundamente.",
        ["...and I'll just stay out of there, thanks. The gods had me dishing out rewards, so I suppose that's my sacred calling now."] = "...y me quedaré fuera de ahí, gracias. Los dioses me hicieron repartir recompensas, así que supongo que ahora esa es mi vocación sagrada.",
        ["I own a couple of fields around these parts, right? So there I am checking on the broccoli one day when Marimbo comes plummeting out of the sky holding a big, plump, green cabbage in one hand."] = "Soy dueño de un par de campos por aquí, ¿verdad? Así que ahí estaba, revisando el brócoli un día cuando Marimbo cae del cielo sosteniendo un repollo verde, grande y regordete en una mano.",
        ["Bless me if the cabbage doesn't begin to speak - says my 'devotion to his people has been noted' and I'm to be 'blessed over all other non-cabbages'. And then the ape pipes up and says I look near enough like one of hers, too."] = "Bendíceme si el repollo no empieza a hablar - dice que mi 'devoción a su pueblo ha sido notada' y seré 'bendecido sobre todos los demás que no son repollos'. Y luego el simio interviene y dice que yo también me parezco bastante a uno de ella.",
        ["I don't know if I like what she was implying."] = "No sé si me gusta lo que estaba insinuando.",
        ["Anyway, she picks me up in the other hand and she jumps about a mile in the air and comes down right here. The rest of it you know."] = "De todos modos, ella me levanta con la otra mano, salta aproximadamente una milla en el aire y cae justo aquí. El resto ya lo sabes.",
        ["So I suppose I'm some sort of priest of Brassica Prime now. Or of Marimbo? Maybe both."] = "Así que supongo que ahora soy una especie de sacerdote de Brassica Prime. ¿O de Marimbo? Quizás ambos.",
        ["I should get a big priesty hat."] = "Debería conseguir un sombrero sacerdotal grande.",
        ["I had other questions."] = "Tenía otras preguntas.",
        ["How do I get involved?"] = "¿Cómo me involucro?",
        ["You're supposed to run back and forth through this arena they've set up and get the highest score you can."] = "Se supone que debes correr de un lado a otro a través de esta arena que han configurado y obtener la puntuación más alta que puedas.",
        ["It's in an underground dungeony sort of place. There's things you can pick up off the ground, and little monkeys you're supposed to punch in the face."] = "Está en una especie de mazmorra subterránea. Hay cosas que puedes recoger del suelo y pequeños monos a los que se supone que debes golpear en the face.",
        ["There's also flames and big gorillas who'll try to punch you in the face. Try not to get punched in the face or burned."] = "También hay llamas y grandes gorilas que intentarán golpearte en the face. Intenta que no te golpeen en the face ni te quemes.",
        ["There's a safe spot at each end where the gorillas can't get you, but they swap back and forth. You'll see a time running after they swap ends."] = "Hay un lugar seguro en cada extremo donde los gorilas no pueden atraparte, pero cambian de un lado a otro. Verás un tiempo corriendo después de que intercambien los extremos.",
        ["Make sure you get to the other end before the timer runs out."] = "Asegúrate de llegar al otro extremo antes de que se acabe el tiempo.",
        ["How does scoring work?"] = "¿Cómo funciona la puntuación?",
        ["Every time you cross the dungeon you'll get some points. Every trophy you pick up along the way off the ground or by punching little monkeys is also worth points."] = "Cada vez que cruces la mazmorra obtendrás algunos puntos. Cada trofeo que recojas en el camino desde el suelo o golpeando a pequeños monos también vale puntos.",
        ["The longer you survive the higher you'll score. And points mean prizes!"] = "Cuanto más sobrevivas, mayor puntuación obtendrás. ¡Y los puntos significan premios!",
        ["What happens if I get knocked out?"] = "¿Qué pasa si me noquean?",
        ["You turn into a gorilla."] = "Te conviertes en un gorila.",
        ["No, seriously. I've seen it happen. Anyone who gets caught outside the safe spot when the timer runs out, or who runs out of heath by being punched or burned or whatever, swells up and goes all hairy."] = "No, en serio. Lo he visto suceder. Cualquiera que quede atrapado fuera del lugar seguro cuando se acaba el tiempo, o que se quede sin salud al recibir un puñetazo, quemarse o lo que sea, se hincha y se pone peludo.",
        ["It's only temporary! Once you come out of the dungeon you're fine again. And while you're a gorilla you get to punch people in the face and that'll get you trophies too, so it's not all bad."] = "¡Es sólo temporal! Una vez que salgas del calabozo estarás bien otra vez. Y mientras eres un gorila, puedes golpear a la gente en the face y eso también te dará trofeos, así que no es del todo malo.",
        ["Tell me about abilities."] = "Háblame de habilidades.",
        ["People can do all sorts of weird stuff down there. I've seen folks walk through walls of fire without flinching, and pick up stuff from metres away without any runes at all."] = "La gente puede hacer todo tipo de cosas raras ahí abajo. He visto gente caminar a través de paredes de fuego sin inmutarse y recoger cosas a metros de distancia sin ninguna runa.",
        ["You can bring one passive and two active abilities into the game, which grant you various advantages. Click on an active ability in the minigame bar to use it during a game. Different abilities have different cooldowns."] = "Puedes incorporar al juego una habilidad pasiva y dos activas, que te otorgan varias ventajas. Haz clic en una habilidad activa en la barra de minijuegos para usarla durante un juego. Diferentes habilidades tienen diferentes tiempos de reutilización.",
        ["What's in it for me?"] = "¿Qué gano yo con esto?",
        ["You can earn experience in several skills, there are items you can buy which help with farming or slayer, and you can unlock new abilities to use in the arena downstairs."] = "Puedes ganar experiencia en varias habilidades, hay artículos que puedes comprar que te ayudarán con la agricultura o el cazador, y puedes desbloquear nuevas habilidades para usar en la arena de abajo.",
        ["Tell me about the reward items."] = "Cuéntame sobre los artículos de recompensa.",
        ["There's three of 'em. The seedicide destroys farming seeds that would drop from monsters you kill, turning them into a chunk of farming experience. You can set what seeds it's allowed to eat."] = "Son tres. El seedicida destruye las semillas agrícolas que caerían de los monstruos que matas, convirtiéndolas en una gran experiencia agrícola. Puedes establecer qué semillas se permite comer.",
        ["The slayer VIP tickets let you choose between two options when you're picking up a new slayer task - there'll be the usual choice as a default, and an alternative you can ask for instead."] = "Los boletos VIP de cazador te permiten elegir entre dos opciones cuando eliges una nueva tarea de cazador: habrá la opción habitual por defecto y una alternativa que puedes solicitar en su lugar.",
        ["The patch bomb is a handy time-saving device! use it on a farming patch and it'll check the health of, harvest, chop down and clear anything that's in it in a single swoop, cleaving it clear for new seeds."] = "¡La bomba parche es un práctico dispositivo para ahorrar tiempo! Úselo en un terreno agrícola y verificará la salud, cosechará, cortará y limpiará todo lo que haya en él de una sola vez, partiéndolo para obtener nuevas semillas.",
        ["Tell me about unlocking abilities."] = "Cuéntame sobre cómo desbloquear habilidades.",
        ["There's a bunch of abilities you can't just use right off the bat, I can sell you unlocks for 'em. Once you've unlocked them, they're yours to use as you want."] = "Hay un montón de habilidades que no puedes usar de inmediato, puedo venderte desbloqueos para ellas. Una vez que los hayas desbloqueado, podrás usarlos como quieras.",
        ["I'd like to manage my abilities and rewards."] = "Me gustaría gestionar mis habilidades y recompensas.",
        ["I'd like to buy rewards."] = "Me gustaría comprar recompensas.",
        ["I'd like to adjust my equipped abilities."] = "Me gustaría ajustar mis habilidades equipadas.",
        ["Actually, I had some questions."] = "En realidad, tenía algunas preguntas.",
        ["Please, tell me... Is there really a gorilla god and a talking cabbage, or was it me drinking all the banana daiquiris?"] = "Por favor, dígame... ¿Existe realmente un dios gorila y un repollo parlante, o fui yo bebiendo todos los daiquiris de plátano?",
        ["No, no...they're real...that happened. But it's okay, they've gone now. You can rest easy."] = "No, no... son reales... eso pasó. Pero está bien, ya se han ido. Puedes estar tranquilo.",
        ["C-can I go back to tending my fields, then?"] = "¿P-puedo volver a cuidar mis campos, entonces?",
        ["Yes, my friend. Go back to your fields."] = "Sí, amigo mío. Vuelve a tus campos.",
        ["I'll Never Get Tired of Cabbage Water"] = "Nunca me cansaré del agua de repollo",
        ["Talk to Vannaka the Slayer Master outside Edgeville dungeon, south of Edgeville."] = "Habla con Vannaka y Slayer Master fuera de la mazmorra Edgeville, al sur de Edgeville.",
        ["Oh, thank you!"] = "¡Oh, gracias!",
        ["Looks like I've completed everything. I'd better go and see Hans about that reward!"] = "Parece que he completado todo. ¡Será mejor que vaya a ver a Hans sobre esa recompensa!",
        ["Short version is, the gods are having people run around in a dungeon full of troops and monkeys, picking up trophies, as some sort of contest. Or maybe some sort of party."] = "La versión corta es que los dioses están haciendo que la gente corra en una mazmorra llena de tropas y monos, recogiendo trofeos, como una especie de concurso. O tal vez algún tipo de fiesta.",
        ["They and that Godless fellow are recruiting people to join in on their behalf, in return for rewards."] = "Ellos y ese tipo impío están reclutando personas para que se unan en su nombre, a cambio de recompensas.",
        ["Well, it seems that Marimbo and Brassica Prime, that's them over there on the fancy thrones -saw the recent fighting between the other gods."] = "Bueno, parece que Marimbo y Brassica Prime, que están allí en los elegantes tronos, vieron la reciente pelea entre los otros dioses.",
        ["I don't think they quite see it as a fight, though. Marimbo's knocking back banana daiquiris like it's going out of style, and Brassica Prime's acting like it's some sort of popularity contest."] = "Aunque no creo que lo vean como una pelea. Marimbo está tomando daiquiris de plátano como si estuviera pasando de moda, y Brassica Prime está actuando como si fuera una especie de concurso de popularidad.",
        ["Then Holstein and Kara-Meir turned up - I'll let him tell that tale, though. Anyway, he's got in on it all too."] = "Entonces aparecieron Holstein y Kara-Meir. Aunque dejaré que él cuente esa historia. De todos modos, él también participa en todo esto.",
        ["...and I'll just stay out of there, thanks. They've got me taking names, and dishing out rewards, for people who join in."] = "...y me quedaré fuera de ahí, gracias. Me tienen tomando nombres y repartiendo recompensas a las personas que se unen.",
        ["How long's it all going on for?"] = "¿Cuánto tiempo dura todo esto?",
        ["Two weeks, they said they'd be here. Don't reckon either of them has the attention span for much more than that, if I'm honest."] = "Dos semanas, dijeron que estarían aquí. No creo que ninguno de ellos tenga capacidad de atención para mucho más que eso, si soy honesto.",
        ["I don't know what they think they're getting out of it. There's none of that green glowy energy stuff left under Lumbridge any more, Saradomin and Zamorak used it all up."] = "No sé qué creen que están obteniendo con esto. Ya no queda nada de esa energía verde brillante bajo Lumbridge, Saradomin y Zamorak la usaron toda.",
        ["But you can bet your life they're not going to think to clean up after themselves when they go. Not seen that sort of politeness from gods."] = "Pero puedes apostar tu vida a que no pensarán en limpiar lo que ensucien cuando se vayan. No he visto ese tipo de cortesía por parte de los dioses.",
        ["How'd you get roped into this?"] = "¿Cómo te involucraste en esto?",
        ["Well, they're having a sort of contest right now. So you tell me what side you're on - maybe talk to them about it first to see which you like better -then you get in the ring there."] = "Bueno, ahora mismo están teniendo una especie de concurso. Así que dime de qué lado estás, tal vez hables con ellos primero para ver cuál te gusta más, y luego te subes al ring.",
        ["The longer you survive the higher you'll score. And points mean prizes! Also glory to your faction, if that rotates your millwheel."] = "Cuanto más sobrevivas, mayor puntuación obtendrás. ¡Y los puntos significan premios! También gloria a tu facción, si eso hace girar tu rueda de molino.",
        ["Well, obviously the glory of supporting your chosen faction is the..."] = "Bueno, obviamente la gloria de apoyar a la facción elegida es...",
        ["...hahaha! No, sorry, couldn't keep a straight face. It's all about the rewards!"] = "...¡jajaja! No, lo siento, no pude mantener la cara seria. ¡Se trata de las recompensas!",
        ["During these two weeks, you can also buy a cape to show off your dedication to your faction."] = "Durante estas dos semanas, también podrás comprar una capa para mostrar tu dedicación a tu facción.",
        ["The farmer looks shifty."] = "El granjero parece sospechoso.",
        ["I'll even let you buy the other capes once you've got your own faction's, because hey! Why not?"] = "Incluso te dejaré comprar las otras capas una vez que tengas tu propia facción, porque ¡oye! ¿Por qué no?",
        ["Tell me about reward items."] = "Cuéntame sobre los artículos de recompensa.",
        ["As the contest goes on I'll let you buy more abilities - check back on day 4 and day 10."] = "A medida que avance el concurso, te dejaré comprar más habilidades. Vuelve a consultar los días 4 y 10.",
        ["I'd like to change my faction."] = "Me gustaría cambiar de facción.",
        ["How would you like to switch sides?"] = "¿Cómo le gustaría cambiar de bando?",
        ["The Godless"] = "Los impíos",
    },
    ["Quartermaster"] = {
        ["Select an Option"] = "Selecciona una opción",
        ["What's going on here?"] = "¿Qué está pasando aquí?",
        ["Well, the short version is that the gods Marimbo and Brassica Prime, and the Godless, had a big contest fight-party near Lumbridge. They're gone now, but the dungeon they created is still around."] = "Bueno, la versión corta es que los dioses Marimbo y Brassica Prime, y los Godless, tuvieron una gran pelea de competencia cerca de Lumbridge. Ya no están, pero la mazmorra que crearon todavía existe.",
        ["You can take this tunnel there and pick up trophies while avoiding traps and guards, and earn rewards for it."] = "Puedes llevar este túnel hasta allí y recoger trofeos mientras evitas trampas y guardias, y ganar recompensas por ello.",
        ["What's the long version?"] = "¿Cuál es la versión larga?",
        ["Well, it seems that Marimbo and Brassica Prime saw the recent fighting between the other gods and decided to join in."] = "Bueno, parece que Marimbo y Brassica Prime vieron la reciente pelea entre los otros dioses y decidieron unirse.",
        ["I don't think they quite saw it as a fight, though. Marimbo knocked back banana daiquiris like it was going out of style, and Brassica Prime was acting like it was some sort of popularity contest."] = "Aunque no creo que lo vieran como una pelea. Marimbo bebió daiquiris de plátano como si estuviera pasando de moda, y Brassica Prime actuaba como si fuera una especie de concurso de popularidad.",
        ["The Godless were in on it too - Holstein and Kara-Meir, although it didn't work out well for her - but they couldn't stop Brassica winning the 'fight'."] = "Los Godless también estuvieron involucrados, Holstein y Kara-Meir, aunque no funcionó bien para ella, pero no pudieron evitar que Brassica ganara la 'pelea'.",
        ["The two gods said something I didn't quite catch, and that big stone plinth just sank into the ground. Now there's a doorway there. Never knew there was a dungeon under these fields."] = "Los dos dioses dijeron algo que no entendí del todo, y ese gran pedestal de piedra simplemente se hundió en el suelo. Ahora hay una puerta allí. Nunca supe que había una mazmorra debajo de estos campos.",
        ["And it's crazy in there! The walls move around and there's fire and monkeys and cabbages and..."] = "¡Y es una locura ahí dentro! Las paredes se mueven y hay fuego y monos y coles y...",
        ["The farmer takes a deep breath."] = "El granjero respira profundamente.",
        ["...and I'll just stay out of there, thanks. The gods had me dishing out rewards, so I suppose that's my sacred calling now."] = "...y me quedaré fuera de ahí, gracias. Los dioses me hicieron repartir recompensas, así que supongo que ahora esa es mi vocación sagrada.",
        ["I own a couple of fields around these parts, right? So there I am checking on the broccoli one day when Marimbo comes plummeting out of the sky holding a big, plump, green cabbage in one hand."] = "Soy dueño de un par de campos por aquí, ¿verdad? Así que ahí estaba, revisando el brócoli un día cuando Marimbo cae del cielo sosteniendo un repollo verde, grande y regordete en una mano.",
        ["Bless me if the cabbage doesn't begin to speak - says my 'devotion to his people has been noted' and I'm to be 'blessed over all other non-cabbages'. And then the ape pipes up and says I look near enough like one of hers, too."] = "Bendíceme si el repollo no empieza a hablar - dice que mi 'devoción a su pueblo ha sido notada' y seré 'bendecido sobre todos los demás que no son repollos'. Y luego el simio interviene y dice que yo también me parezco bastante a uno de ella.",
        ["I don't know if I like what she was implying."] = "No sé si me gusta lo que estaba insinuando.",
        ["Anyway, she picks me up in the other hand and she jumps about a mile in the air and comes down right here. The rest of it you know."] = "De todos modos, ella me levanta con la otra mano, salta aproximadamente una milla en el aire y cae justo aquí. El resto ya lo sabes.",
        ["So I suppose I'm some sort of priest of Brassica Prime now. Or of Marimbo? Maybe both."] = "Así que supongo que ahora soy una especie de sacerdote de Brassica Prime. ¿O de Marimbo? Quizás ambos.",
        ["I should get a big priesty hat."] = "Debería conseguir un sombrero sacerdotal grande.",
        ["I had other questions."] = "Tenía otras preguntas.",
        ["How do I get involved?"] = "¿Cómo me involucro?",
        ["You're supposed to run back and forth through this arena they've set up and get the highest score you can."] = "Se supone que debes correr de un lado a otro a través de esta arena que han configurado y obtener la puntuación más alta que puedas.",
        ["It's in an underground dungeony sort of place. There's things you can pick up off the ground, and little monkeys you're supposed to punch in the face."] = "Está en una especie de mazmorra subterránea. Hay cosas que puedes recoger del suelo y pequeños monos a los que se supone que debes golpear en the face.",
        ["There's also flames and big gorillas who'll try to punch you in the face. Try not to get punched in the face or burned."] = "También hay llamas y grandes gorilas que intentarán golpearte en the face. Intenta que no te golpeen en the face ni te quemes.",
        ["There's a safe spot at each end where the gorillas can't get you, but they swap back and forth. You'll see a time running after they swap ends."] = "Hay un lugar seguro en cada extremo donde los gorilas no pueden atraparte, pero cambian de un lado a otro. Verás un tiempo corriendo después de que intercambien los extremos.",
        ["Make sure you get to the other end before the timer runs out."] = "Asegúrate de llegar al otro extremo antes de que se acabe el tiempo.",
        ["How does scoring work?"] = "¿Cómo funciona la puntuación?",
        ["Every time you cross the dungeon you'll get some points. Every trophy you pick up along the way off the ground or by punching little monkeys is also worth points."] = "Cada vez que cruces la mazmorra obtendrás algunos puntos. Cada trofeo que recojas en el camino desde el suelo o golpeando a pequeños monos también vale puntos.",
        ["The longer you survive the higher you'll score. And points mean prizes!"] = "Cuanto más sobrevivas, mayor puntuación obtendrás. ¡Y los puntos significan premios!",
        ["What happens if I get knocked out?"] = "¿Qué pasa si me noquean?",
        ["You turn into a gorilla."] = "Te conviertes en un gorila.",
        ["No, seriously. I've seen it happen. Anyone who gets caught outside the safe spot when the timer runs out, or who runs out of heath by being punched or burned or whatever, swells up and goes all hairy."] = "No, en serio. Lo he visto suceder. Cualquiera que quede atrapado fuera del lugar seguro cuando se acaba el tiempo, o que se quede sin salud al recibir un puñetazo, quemarse o lo que sea, se hincha y se pone peludo.",
        ["It's only temporary! Once you come out of the dungeon you're fine again. And while you're a gorilla you get to punch people in the face and that'll get you trophies too, so it's not all bad."] = "¡Es sólo temporal! Una vez que salgas del calabozo estarás bien otra vez. Y mientras eres un gorila, puedes golpear a la gente en the face y eso también te dará trofeos, así que no es del todo malo.",
        ["Tell me about abilities."] = "Háblame de habilidades.",
        ["People can do all sorts of weird stuff down there. I've seen folks walk through walls of fire without flinching, and pick up stuff from metres away without any runes at all."] = "La gente puede hacer todo tipo de cosas raras ahí abajo. He visto gente caminar a través de paredes de fuego sin inmutarse y recoger cosas a metros de distancia sin ninguna runa.",
        ["You can bring one passive and two active abilities into the game, which grant you various advantages. Click on an active ability in the minigame bar to use it during a game. Different abilities have different cooldowns."] = "Puedes incorporar al juego una habilidad pasiva y dos activas, que te otorgan varias ventajas. Haz clic en una habilidad activa en la barra de minijuegos para usarla durante un juego. Diferentes habilidades tienen diferentes tiempos de reutilización.",
        ["What's in it for me?"] = "¿Qué gano yo con esto?",
        ["You can earn experience in several skills, there are items you can buy which help with farming or slayer, and you can unlock new abilities to use in the arena downstairs."] = "Puedes ganar experiencia en varias habilidades, hay artículos que puedes comprar que te ayudarán con la agricultura o el cazador, y puedes desbloquear nuevas habilidades para usar en la arena de abajo.",
        ["Tell me about the reward items."] = "Cuéntame sobre los artículos de recompensa.",
        ["There's three of 'em. The seedicide destroys farming seeds that would drop from monsters you kill, turning them into a chunk of farming experience. You can set what seeds it's allowed to eat."] = "Son tres. El seedicida destruye las semillas agrícolas que caerían de los monstruos que matas, convirtiéndolas en una gran experiencia agrícola. Puedes establecer qué semillas se permite comer.",
        ["The slayer VIP tickets let you choose between two options when you're picking up a new slayer task - there'll be the usual choice as a default, and an alternative you can ask for instead."] = "Los boletos VIP de cazador te permiten elegir entre dos opciones cuando eliges una nueva tarea de cazador: habrá la opción habitual por defecto y una alternativa que puedes solicitar en su lugar.",
        ["The patch bomb is a handy time-saving device! use it on a farming patch and it'll check the health of, harvest, chop down and clear anything that's in it in a single swoop, cleaving it clear for new seeds."] = "¡La bomba parche es un práctico dispositivo para ahorrar tiempo! Úselo en un terreno agrícola y verificará la salud, cosechará, cortará y limpiará todo lo que haya en él de una sola vez, partiéndolo para obtener nuevas semillas.",
        ["Tell me about unlocking abilities."] = "Cuéntame sobre cómo desbloquear habilidades.",
        ["There's a bunch of abilities you can't just use right off the bat, I can sell you unlocks for 'em. Once you've unlocked them, they're yours to use as you want."] = "Hay un montón de habilidades que no puedes usar de inmediato, puedo venderte desbloqueos para ellas. Una vez que los hayas desbloqueado, podrás usarlos como quieras.",
        ["I'd like to manage my abilities and rewards."] = "Me gustaría gestionar mis habilidades y recompensas.",
        ["I'd like to buy rewards."] = "Me gustaría comprar recompensas.",
        ["I'd like to adjust my equipped abilities."] = "Me gustaría ajustar mis habilidades equipadas.",
        ["Actually, I had some questions."] = "En realidad, tenía algunas preguntas.",
        ["Please, tell me... Is there really a gorilla god and a talking cabbage, or was it me drinking all the banana daiquiris?"] = "Por favor, dígame... ¿Existe realmente un dios gorila y un repollo parlante, o fui yo bebiendo todos los daiquiris de plátano?",
        ["No, no...they're real...that happened. But it's okay, they've gone now. You can rest easy."] = "No, no... son reales... eso pasó. Pero está bien, ya se han ido. Puedes estar tranquilo.",
        ["C-can I go back to tending my fields, then?"] = "¿P-puedo volver a cuidar mis campos, entonces?",
        ["Yes, my friend. Go back to your fields."] = "Sí, amigo mío. Vuelve a tus campos.",
        ["I'll Never Get Tired of Cabbage Water"] = "Nunca me cansaré del agua de repollo",
        ["Talk to Vannaka the Slayer Master outside Edgeville dungeon, south of Edgeville."] = "Habla con Vannaka y Slayer Master fuera de la mazmorra Edgeville, al sur de Edgeville.",
        ["Oh, thank you!"] = "¡Oh, gracias!",
        ["Looks like I've completed everything. I'd better go and see Hans about that reward!"] = "Parece que he completado todo. ¡Será mejor que vaya a ver a Hans sobre esa recompensa!",
        ["Short version is, the gods are having people run around in a dungeon full of troops and monkeys, picking up trophies, as some sort of contest. Or maybe some sort of party."] = "La versión corta es que los dioses están haciendo que la gente corra en una mazmorra llena de tropas y monos, recogiendo trofeos, como una especie de concurso. O tal vez algún tipo de fiesta.",
        ["They and that Godless fellow are recruiting people to join in on their behalf, in return for rewards."] = "Ellos y ese tipo impío están reclutando personas para que se unan en su nombre, a cambio de recompensas.",
        ["Well, it seems that Marimbo and Brassica Prime, that's them over there on the fancy thrones -saw the recent fighting between the other gods."] = "Bueno, parece que Marimbo y Brassica Prime, que están allí en los elegantes tronos, vieron la reciente pelea entre los otros dioses.",
        ["I don't think they quite see it as a fight, though. Marimbo's knocking back banana daiquiris like it's going out of style, and Brassica Prime's acting like it's some sort of popularity contest."] = "Aunque no creo que lo vean como una pelea. Marimbo está tomando daiquiris de plátano como si estuviera pasando de moda, y Brassica Prime está actuando como si fuera una especie de concurso de popularidad.",
        ["Then Holstein and Kara-Meir turned up - I'll let him tell that tale, though. Anyway, he's got in on it all too."] = "Entonces aparecieron Holstein y Kara-Meir. Aunque dejaré que él cuente esa historia. De todos modos, él también participa en todo esto.",
        ["...and I'll just stay out of there, thanks. They've got me taking names, and dishing out rewards, for people who join in."] = "...y me quedaré fuera de ahí, gracias. Me tienen tomando nombres y repartiendo recompensas a las personas que se unen.",
        ["How long's it all going on for?"] = "¿Cuánto tiempo dura todo esto?",
        ["Two weeks, they said they'd be here. Don't reckon either of them has the attention span for much more than that, if I'm honest."] = "Dos semanas, dijeron que estarían aquí. No creo que ninguno de ellos tenga capacidad de atención para mucho más que eso, si soy honesto.",
        ["I don't know what they think they're getting out of it. There's none of that green glowy energy stuff left under Lumbridge any more, Saradomin and Zamorak used it all up."] = "No sé qué creen que están obteniendo con esto. Ya no queda nada de esa energía verde brillante bajo Lumbridge, Saradomin y Zamorak la usaron toda.",
        ["But you can bet your life they're not going to think to clean up after themselves when they go. Not seen that sort of politeness from gods."] = "Pero puedes apostar tu vida a que no pensarán en limpiar lo que ensucien cuando se vayan. No he visto ese tipo de cortesía por parte de los dioses.",
        ["How'd you get roped into this?"] = "¿Cómo te involucraste en esto?",
        ["Well, they're having a sort of contest right now. So you tell me what side you're on - maybe talk to them about it first to see which you like better -then you get in the ring there."] = "Bueno, ahora mismo están teniendo una especie de concurso. Así que dime de qué lado estás, tal vez hables con ellos primero para ver cuál te gusta más, y luego te subes al ring.",
        ["The longer you survive the higher you'll score. And points mean prizes! Also glory to your faction, if that rotates your millwheel."] = "Cuanto más sobrevivas, mayor puntuación obtendrás. ¡Y los puntos significan premios! También gloria a tu facción, si eso hace girar tu rueda de molino.",
        ["Well, obviously the glory of supporting your chosen faction is the..."] = "Bueno, obviamente la gloria de apoyar a la facción elegida es...",
        ["...hahaha! No, sorry, couldn't keep a straight face. It's all about the rewards!"] = "...¡jajaja! No, lo siento, no pude mantener la cara seria. ¡Se trata de las recompensas!",
        ["During these two weeks, you can also buy a cape to show off your dedication to your faction."] = "Durante estas dos semanas, también podrás comprar una capa para mostrar tu dedicación a tu facción.",
        ["The farmer looks shifty."] = "El granjero parece sospechoso.",
        ["I'll even let you buy the other capes once you've got your own faction's, because hey! Why not?"] = "Incluso te dejaré comprar las otras capas una vez que tengas tu propia facción, porque ¡oye! ¿Por qué no?",
        ["Tell me about reward items."] = "Cuéntame sobre los artículos de recompensa.",
        ["As the contest goes on I'll let you buy more abilities - check back on day 4 and day 10."] = "A medida que avance el concurso, te dejaré comprar más habilidades. Vuelve a consultar los días 4 y 10.",
        ["I'd like to change my faction."] = "Me gustaría cambiar de facción.",
        ["How would you like to switch sides?"] = "¿Cómo le gustaría cambiar de bando?",
        ["The Godless"] = "Los impíos",
    },
    ["Quartermaster (Clan Citadels)"] = {
        ["Good day to you! How may I assist?"] = "¡Buenos días! ¿Cómo puedo ayudar?",
        ["Choose an option:"] = "Elige una opción:",
        ["What do you do here?"] = "¿Qué haces aquí?",
        ["I'm the quartermaster for your clan. I keep track of the jobs you or your clanmates have marked to be undertaken within the citadel; the resources it will take; and whether you can meet that requirement."] = "Soy el intendente de tu clan. Llevo un registro de los trabajos que tú o tus compañeros de clan habéis marcado para realizar dentro de la ciudadela; los recursos que se necesitarán; y si puede cumplir con ese requisito.",
        ["I am also capable of altering the day on which your buildings are altered and the resources used up, and I can award bonus experience."] = "También soy capaz de alterar el día en el que se modifican tus edificios y los recursos utilizados, y puedo otorgar experiencia adicional.",
        ["Select an Option"] = "Selecciona una opción",
        ["Tell me more about the job list."] = "Cuéntame más sobre la lista de trabajos.",
        ["On the job list you will see all downgrades, upkeep dues, and upgrade requests pending for your clan's citadel. Upkeep jobs will remain as long as you have a building in your citadel requiring upkeep; the others are removed when they are carried out."] = "En la lista de trabajos verás todas las solicitudes de degradación, cuotas de mantenimiento y mejoras pendientes para la ciudadela de tu clan. Los trabajos de mantenimiento permanecerán mientras tengas un edificio en tu ciudadela que requiera mantenimiento; los demás se eliminan cuando se llevan a cabo.",
        ["You may click on jobs in the list to view more information regarding their costs, and the resources available to perform those jobs, and any warnings related to jobs which currently have shortfall or unmet requirements."] = "Puede hacer clic en los trabajos de la lista para ver más información sobre sus costos y los recursos disponibles para realizar esos trabajos, y cualquier advertencia relacionada con trabajos que actualmente tienen requisitos insuficientes o no cumplidos.",
        ["If you have the requisite access permissions from your clan's officers, you may alter the list by dragging jobs to reorder them, or to cancel downgrade or upgrade jobs."] = "Si tienes los permisos de acceso necesarios de los oficiales de tu clan, puedes modificar la lista arrastrando trabajos para reordenarlos o cancelar trabajos de degradación o mejora.",
        ["You may also jump from upgrade jobs to the build interface to make alterations if need be, but that's more the artisan's area than mine, quite frankly."] = "También puedes pasar de los trabajos de actualización a la interfaz de construcción para realizar modificaciones si es necesario, pero, francamente, esa es más área del artesano que mía.",
        ["Would you like to open the list now?"] = "¿Quieres abrir la lista ahora?",
        ["Yes"] = "si",
        ["*(Job list interface opens)*"] = "*(Se abre la interfaz de lista de trabajos)*",
        ["Tell me about moving the build tick."] = "Cuéntame cómo mover el tick de compilación.",
        ["The owner, deputy or overseer of a clan may move the build tick to a day of the week and time of day more suitable for your clan's activity. Just talk to me about it and I will set your build tick to be due precisely one week from that moment."] = "El propietario, diputado o supervisor de un clan puede mover la marca de construcción a un día de la semana y a una hora del día más adecuada para la actividad de su clan. Sólo háblame al respecto y configuraré tu tick de compilación para que venza exactamente una semana a partir de ese momento.",
        ["I must warn you, though, that it will cost you a week's upkeep up front to do so. You will be allowed to do it only once per week and you may not move the tick to the same day on which it already falls."] = "Debo advertirle, sin embargo, que hacerlo le costará una semana de mantenimiento por adelantado. Se te permitirá hacerlo sólo una vez por semana y no podrás mover la garrapata al mismo día en el que ya cae.",
        ["Moving the build tick will also not carry out any upgrade or downgrade jobs you have listed."] = "Mover la marca de compilación tampoco llevará a cabo ningún trabajo de actualización o degradación que hayas enumerado.",
        ["Do you wish to move the build tick?"] = "¿Desea mover el tick de compilación?",
        ["Your rank is not high enough to move your clan's build/upkeep day."] = "Tu rango no es lo suficientemente alto como para cambiar el día de construcción/mantenimiento de tu clan.",
        ["About experience boosts..."] = "Acerca de los aumentos de experiencia...",
        ["I'm afraid I've given you experience rather recently, and as you're new to the clan I can't give you more for at least another day."] = "Me temo que te he dado experiencia hace poco y como eres nuevo en el clan no puedo darte más hasta al menos hasta dentro de un día.",
        ["I've already given you some experience; I won't be able to give you more until after the next build cycle."] = "Ya te he dado algo de experiencia; No podré darte más hasta después del próximo ciclo de construcción.",
        ["Can you give me some experience?"] = "¿Puedes darme alguna experiencia?",
        ["As you work for your clan, gathering resources we need for building and maintaining the Stronghold, you will make progress towards earning an experience boost. You will be able to use up the bonus experience both here in the citadel and out in the rest of the world."] = "A medida que trabajes para tu clan, reuniendo los recursos que necesitamos para construir y mantener la Fortaleza, progresarás para obtener un aumento de experiencia. Podrás utilizar la experiencia adicional tanto aquí en la ciudadela como en el resto del mundo.",
        ["I must warn you that I can only provide one bonus per week."] = "Debo advertirles que solo puedo ofrecer un bono por semana.",
        ["Now, let's see..."] = "Ahora, veamos...",
        ["Our records show that you have done no work for us this week."] = "Nuestros registros muestran que no ha trabajado para nosotros esta semana.",
        ["Yes; you've done enough work to earn experience. Which skill would you like it in?"] = "Sí; has trabajado suficiente para ganar experiencia. ¿En qué habilidad te gustaría hacerlo?",
        ["How can I earn bonus experience?"] = "¿Cómo puedo ganar experiencia extra?",
        ["Earning the boost is simply a matter of working in any of our resource-gathering buildings, from the Woodcutting tree up to the Summoning grove. Once you've gathered enough, spread however you wish between the plots available to the clan, I can grant you the bonus."] = "Obtener el impulso es simplemente cuestión de trabajar en cualquiera de nuestros edificios de recolección de recursos, desde el árbol Woodcutting hasta la arboleda Summoning. Una vez que hayas reunido lo suficiente, reparte como quieras entre las parcelas disponibles para el clan, puedo otorgarte el bono.",
        ["I'm here for an experience boost"] = "Estoy aquí para un impulso de experiencia.",
        ["I'm terribly sorry. You'll need to do more work before I can give you experience."] = "Lo siento mucho. Necesitarás trabajar más antes de que pueda brindarte experiencia.",
        ["I'd like to check the Job list."] = "Me gustaría consultar la lista de trabajos.",
        ["I'd like to move the Clan's build tick."] = "Me gustaría mover el tick de construcción del clan.",
        ["About bonus experience..."] = "Acerca de la experiencia adicional...",
        ["Can you sell me some Clan Citadel Boosters?"] = "¿Puedes venderme algunos potenciadores de la Ciudadela del clan?",
        ["Of course! How many do you want?"] = "¡Por supuesto! ¿Cuantos quieres?",
        ["How many would you like to buy?"] = "¿Cuántos te gustaría comprar?",
        ["One."] = "Uno.",
        ["Three."] = "Tres.",
        ["Six."] = "Seis.",
        ["None, I changed my mind."] = "Ninguno, cambié de opinión.",
    },
    ["Quartermaster (Tyras Camp)"] = {
        ["Good day [Sir/Miss]. I'm the quartermaster for King Tyras's camp. We have a little we could trade here. We have a new stock of dragon halberds. Would you like a look at what we have now?"] = "Buenos días [Sir/Miss]. Soy el intendente del campamento del rey Tyras. Tenemos un poco que podríamos intercambiar aquí. Disponemos de un nuevo stock de alabardas de dragón. ¿Quieres ver lo que tenemos ahora?",
        ["Select an option"] = "Seleccione una opción",
        ["Yes please. What are you selling?"] = "Sí por favor. ¿Qué estás vendiendo?",
        ["No thanks."] = "No, gracias.",
    },
    ["Quartermaster Gully"] = {
        ["Are ye ready to set sail for the Arc, Cap'n?"] = "¿Está listo para zarpar hacia el Arco, Capitán?",
        ["Where would you suggest we go first?"] = "¿Dónde sugieres que vayamos primero?",
        ["Hmm, that'd have to be Waiko. It's the main hub of where east meets west."] = "Hmm, ese tendría que ser Waiko. Es el centro principal donde el este se encuentra con el oeste.",
        ["Jed would no doubt have stopped there to stock up on supplies."] = "Jed sin duda se habría detenido allí para abastecerse de suministros.",
        ["Very good, Gully. Let's set sail!"] = "Muy bien, Gully. ¡Zarpemos!",
        ["Ready to sail whenever you are, cap'n."] = "Listo para navegar cuando usted lo desee, capitán.",
        ["*(The Arc interface opens.)*"] = "*(Se abre la interfaz de Arc.)*",
        ["Cap'n. I'll stock up the ship from the market. We'll be ready to set sail again whenever you're ready."] = "Capitán. Abasteceré el barco en el mercado. Estaremos listos para zarpar nuevamente cuando usted esté listo.",
        ["Gully, do you mind if I ask, what's going on with your hat?"] = "Gully, ¿te importa si te pregunto qué está pasando con tu sombrero?",
        ["It's a septicorn, Cap'n."] = "Es un septicornio, Capitán.",
        ["I thought tricorns were the fashion."] = "Pensé que los tricornios estaban de moda.",
        ["Aye, if you're just aiming for 'sailor', but I like to go the extra nautical mile! And septicorns are more than twice as good as tricorns {{nbsp}}that's math!"] = "Sí, si solo buscas ser 'marinero', ¡pero a mí me gusta hacer un esfuerzo náutico adicional! Y los septicornio son más del doble de buenos que los tricornio {{nbsp}} ¡Eso es matemática!",
        ["Calm down, Steven. You're not having any fish, you get fed too much as it is."] = "Cálmate, Steven. No comes pescado, te alimentan demasiado.",
        ["And I do wish you'd stop 'dropping feathers' down the back of my coat."] = "Y desearía que dejaras de \"dejar caer plumas\" por la parte de atrás de mi abrigo.",
        ["Wow, your seagull actually drops feathers?"] = "Vaya, ¿a tu gaviota se le caen plumas?",
        ["Er, no. It's a euphemism."] = "Eh, no. Es un eufemismo.",
        ["They ain't feathers."] = "No son plumas.",
        ["It's poop."] = "Es caca.",
        ["Yes, I got that, thank you."] = "Sí, lo entendí, gracias.",
        ["So, Gully, what's the deal with you, shall we say, over-embellishing the whole pirate thing?"] = "Entonces, Gully, ¿qué te pasa, digamos, embelleciendo demasiado todo el asunto de los piratas?",
        ["What do you mean, Cap'n?"] = "¿Qué quiere decir, Capitán?",
        ["The overwrought hat, the outfit, the what can only be described as a mega-hook, all the pirate trimmings the...seagull?"] = "El sombrero sobrecargado, el traje, lo que sólo puede describirse como un megagancho, todos los adornos piratas, ¿la gaviota?",
        ["The seagull."] = "La gaviota.",
        ["The seagull is called Steven."] = "La gaviota se llama Steven.",
        ["Okay, and...Steven."] = "Está bien, y... Steven.",
        ["I'm the most piratically piratey pirate you ever did see. There's no mistaking the very piratical nature of my pirate-ness."] = "Soy el pirata más pirata que jamás hayas visto. No hay duda de la naturaleza pirata de mi piratería.",
        ["If you cut me to my core it'd say 'pirate' through the middle."] = "Si me cortas hasta la médula, diría \"pirata\" en el medio.",
        ["Well, sure, but now I just have completely different questions."] = "Bueno, claro, pero ahora tengo preguntas completamente diferentes.",
        ["This here be the land of giants, Cap'n. Tread carefully, lest you be stepped upon."] = "Ésta es la tierra de los gigantes, Capitán. Andad con cuidado, no sea que os pisoteen.",
        ["Ah, now this be more to the taste of Steven and meself. I hear there's a colony of gnomes on this sunny island, and they brew a particularly potent rum from sweet local berries."] = "Ah, ahora esto será más del gusto de Steven y mío. He oído que hay una colonia de gnomos en esta isla soleada y elaboran un ron particularmente potente del dulce local berries.",
        ["This here be the Islands That Once Were Turtles, mate. There's a chill to this place that shivers me down to my very timbers."] = "Estas son las islas que alguna vez fueron tortugas, amigo. Hay un escalofrío en este lugar que me estremece hasta las entrañas.",
        ["You're trying mighty hard to talk like a pirate, Mister Gully. Almost too hard."] = "Está intentando con todas sus fuerzas hablar como un pirata, señor Gully. Casi demasiado duro.",
        ["Aye."] = "Sí.",
        ["I'd still rather we didn't linger here, Cap'n. Watch yourself."] = "Aún así preferiría que no nos quedáramos aquí, Capitán. Mírate a ti mismo.",
        ["The city of Gongdung be a tomb, Cap'n. A sealed tomb."] = "La ciudad de Gongdung será una tumba, Capitán. Una tumba sellada.",
        ["There ain't no treasure to be found here...only the dead, or worse. Let's be away."] = "No se puede encontrar ningún tesoro aquí... sólo los muertos, o algo peor. Vámonos lejos.",
        ["I'm not sure about this, Cap'n. Somethin' 'bout this place feels off..."] = "No estoy seguro de esto, Capitán. Algo en este lugar se siente mal...",
        ["An' if you need something more specific, I don't trust that Wadud fella."] = "Y si necesitas algo más específico, no confío en ese tipo Wadud.",
        ["He's bin by a few times since we anchored, and each time he's bin eyeing up the Revenge."] = "Ha pasado varias veces desde que anclamos, y cada vez está mirando el Revenge.",
        ["Aye, Steven. If he tries anything, go fer his eyes."] = "Sí, Steven. Si intenta algo, ve por sus ojos.",
        ["I see ye have a treasure map there, cap'n - would you like to sail to that uncharted region?"] = "Veo que tiene un mapa del tesoro allí, capitán. ¿Le gustaría navegar a esa región inexplorada?",
        ["Sail to treasure island?"] = "¿Navegar a la isla del tesoro?",
        ["Yes."] = "Sí.",
        ["Select an option"] = "Selecciona una opción",
        ["Where would you like to sail?"] = "¿Dónde te gustaría navegar?",
        ["Milky Bay"] = "Bahía Láctea",
        ["The Goon Docks"] = "Los muelles del matón",
        ["Christmas Island"] = "Isla de Navidad",
        ["Springbreak Island"] = "Isla de vacaciones de primavera",
        ["Cannonball Run"] = "Carrera de bala de cañón",
        ["The Hamlet"] = "la aldea",
        ["Quis-land"] = "tierra de quis",
        ["Agar Atoll"] = "Atolón de Agar",
        ["I see ye have a map to a remote uncharted island there, cap'n - would you like to sail there? It won't even cost us any supplies!"] = "Veo que tiene un mapa de una isla remota e inexplorada, capitán. ¿Le gustaría navegar allí? ¡Ni siquiera nos costará suministros!",
        ["Sail to Uncharted Island?"] = "¿Navegar a la isla inexplorada?",
        ["Yes"] = "si",
        ["*(Player is taken to uncharted island.)*"] = "*(Player es llevado a una isla inexplorada.)*",
        ["I see ye have one of those special maps to a remote uncharted island there, cap'n - I hear these islands are full of resources, would you like to sail there? It won't even cost us any supplies!"] = "Veo que tiene uno de esos mapas especiales de una isla remota e inexplorada, capitán. He oído que estas islas están llenas de recursos, ¿le gustaría navegar allí? ¡Ni siquiera nos costará suministros!",
    },
    ["Queen Elizabuzz"] = {
        ["[You spot a bee and find 100 Nectar!]"] = "[¡Ves una abeja y encuentras 100 néctar!]",
        ["[You spot another bee and collect 100 Nectar!]"] = "[¡Ves otra abeja y recolectas 100 néctar!]",
        ["I wonder if this has anything to do with the person that just arrived in Falador?"] = "Me pregunto si esto tiene algo que ver con la persona que acaba de llegar a Falador.",
        ["I've already spotted this {{Sic|Bee}}!"] = "¡Ya vi este {{Sic|Bee}}!",
        ["I've already found all of the bees!"] = "¡Ya encontré todas las abejas!",
        ["What an awesome bee!"] = "¡Qué abeja tan increíble!",
    },
    ["Queen Sigrid"] = {
        ["Hello."] = "Hola.",
        ["Er...Hello, Your Majesty."] = "Er... Hola, Su Majestad.",
        ["Have you come for a particular reason? I am a busy Queen, you know. I had to attend the opening of a new orphanage this morning."] = "¿Has venido por algún motivo en particular? Soy una reina ocupada, ¿sabes? Esta mañana tuve que asistir a la inauguración de un nuevo orfanato.",
        ["Yes, I..."] = "Sí, yo...",
        ["And this afternoon I shall be receiving the Embassador of Karamja and accompanying him on his week-long tour of Etceteria."] = "Y esta tarde recibiré al Embajador de Karamja y lo acompañaré en su gira de una semana por Etceteria.",
        ["Er, I..."] = "Eh, yo...",
        ["Then this evening we shall be putting on a grand ball! All of the kingdom's nobility will be present!"] = "¡Entonces esta noche organizaremos un gran baile! ¡Toda la nobleza del reino estará presente!",
        ["If I m..."] = "Si yo...",
        ["Oh, who am I kidding...nothing ever happens here. I always wanted to be a princess when I was a girl. If I'd been told it would be like this, I wouldn't have bothered."] = "Oh, ¿a quién engaño? Aquí nunca pasa nada. Siempre quise ser princesa cuando era niña. Si me hubieran dicho que sería así, no me habría molestado.",
        ["Your Majesty!"] = "¡Su Majestad!",
        ["Yes? Did you want something?"] = "¿Sí? ¿Querías algo?",
        ["...actually, no."] = "...en realidad, no.",
        ["Thank you for all your help, [Fremennik Name]. It's good to know that the Regent of Miscellania is willing to help his neighbours."] = "Gracias por toda tu ayuda, [Fremennik Name]. Es bueno saber que el Regente de Miscellania está dispuesto a ayudar a sus vecinos.",
        ["You're welcome, Your Majesty."] = "De nada, Su Majestad.",
        ["Thank you for everything, [Fremennik name]. It was hard to move out of my beloved castle, but worth it to be with my husband."] = "Gracias por todo, [Fremennik name]. Fue difícil mudarme de mi querido castillo, pero valió la pena estar con mi marido.",
        ["Ah, this puzzle is yours, I take it?"] = "Ah, este rompecabezas es tuyo, ¿lo entiendo?",
        ["[Queen Sigrid has given you a puzzle box!]"] = "[¡Queen Sigrid te ha regalado una caja de rompecabezas!]",
        ["Is that the best you can do? Try harder!"] = "¿Es eso lo mejor que puedes hacer? ¡Esfuérzate más!",
        ["[Queen Sigrid has given you another clue scroll!]"] = "[¡Queen Sigrid te ha dado otro pergamino de pistas!]",
        ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
        ["Great; there is the reward."] = "Genial; ahí está la recompensa.",
    },
    ["Queen of Snow"] = {
        ["The snow tournament draws to a close. I look forward to seeing you again next Wintumber, noble traveller!"] = "El torneo de nieve llega a su fin. ¡Espero volver a verte el próximo Wintumber, noble viajero!",
        ["Thank you for helping me enjoy the 'great' snow tournament for what it is, and take the festivities less seriously."] = "Gracias por ayudarme a disfrutar del 'gran' torneo de nieve tal como es y a tomarme las festividades menos en serio.",
        ["Select an Option"] = "Seleccione una opción",
        ["Who are you?"] = "¿Quién eres?",
        ["I am the Queen of Snow. The all-wise Guthix placed me in command of the forces of snow and ice that dominate the winter of each year."] = "Yo soy el Queen of Snow. El omnisciente Guthix me puso al mando de las fuerzas de la nieve y el hielo que dominan el invierno de cada año.",
        ["To what extent, as monarch of this land, I remain my mother's daughter and successor to my sister is an interesting philosophical question."] = "Hasta qué punto, como monarca de esta tierra, sigo siendo hija de mi madre y sucesora de mi hermana es una cuestión filosófica interesante.",
        ["Does the head fit the crown or the crown fit the head?"] = "¿La cabeza se ajusta a la corona o la corona se ajusta a la cabeza?",
        ["In becoming the personification of winter, have I ceased to be a young ice sprite named Lumi?"] = "Al convertirme en la personificación del invierno, ¿he dejado de ser un joven duende del hielo llamado Lumi?",
        ["Ultimately, the question is irrelevant. I am what I am, and I shall remain irrevocably transformed, whether by the weight of responsibility or the role I inhabit, until I, too, return to snow or vacate the throne."] = "En última instancia, la pregunta es irrelevante. Soy lo que soy y permaneceré irrevocablemente transformado, ya sea por el peso de la responsabilidad o por el papel que desempeño, hasta que yo también regrese a la nieve o deje el trono.",
        ["What is an ice sprite?"] = "¿Qué es un duende de hielo?",
        ["Ice sprites trace our lineage to the King of Roses and Queen of Snow. Direct descendants are usually potential candidates to perpetuate the monarchy."] = "Los duendes de hielo remontan nuestro linaje al Rey de las Rosas y Queen of Snow. Los descendientes directos suelen ser candidatos potenciales para perpetuar la monarquía.",
        ["Given their political importance, ice sprite princesses and princes are typically not allowed to leave the Land of Snow unless an appeal is granted."] = "Dada su importancia política, a las princesas y príncipes duendes de hielo normalmente no se les permite abandonar la Tierra de la Nieve a menos que se conceda una apelación.",
        ["Ice sprites are mortal, like you humans, but longer-lived."] = "Los duendes de hielo son mortales, como ustedes los humanos, pero viven más tiempo.",
        ["Reductively speaking, we can also play with cold and water."] = "Reductivamente hablando, también podemos jugar con frío y agua.",
        ["You've met the god of balance?"] = "¿Has conocido al dios del equilibrio?",
        ["Well, not personally.<br>But so my father declared (with much conviction) when I ascended the throne at my coronation."] = "Bueno, personalmente no.<br>Pero eso declaró mi padre (con mucha convicción) cuando ascendí al trono en mi coronación.",
        ["I am obligated to perpetuate that declaration.<br>Such beliefs can be comfortably reassuring."] = "Estoy obligado a perpetuar esa declaración.<br>Estas creencias pueden resultar cómodamente tranquilizadoras.",
        ["I have a different question..."] = "Tengo una pregunta diferente...",
        ["What is the Land of Snow?"] = "¿Qué es la Tierra de la Nieve?",
        ["The Land of Snow is where snowmen dance and never melt, celebrating winter all year long."] = "La Tierra de la Nieve es donde los muñecos de nieve bailan y nunca se derriten, celebrando el invierno durante todo el año.",
        ["This land was created aeons ago by Guthix, as part of his balancing of your world."] = "Esta tierra fue creada hace eones por Guthix, como parte de su equilibrio de tu mundo.",
        ["The cold of the Land of Snow counteracts the perpetual heat of its counterpart, the Land of Sunlight, ensuring the correct and comfortable balance of hot and cold in Gielinor."] = "El frío de la Tierra de la Nieve contrarresta el calor perpetuo de su contraparte, la Tierra de la Luz del Sol, asegurando el correcto y confortable equilibrio entre calor y frío en Gielinor.",
        ["Here in the Land of Snow, it is winter all year 'round, with bright clear stars overhead and crisp snow underfoot. To us, there is no 'last Christmas' or 'next Christmas'. It is always Christmas."] = "Aquí, en la Tierra de la Nieve, es invierno todo el año, con estrellas brillantes y claras en lo alto y nieve crujiente bajo los pies. Para nosotros no existe la “última Navidad” ni la “próxima Navidad”. Siempre es Navidad.",
        ["This is the realm where winter weather, and the very idea of snow, originates. During winter, your world is aligned to the Land of Snow; close enough to visit, for a short time."] = "Este es el reino donde se origina el clima invernal y la idea misma de la nieve. Durante el invierno, vuestro mundo está alineado con la Tierra de la Nieve; lo suficientemente cerca para visitarlo, por un corto tiempo.",
        ["Every visitor to the Land of Snow, every snowball thrown and snowman made, sends echoes of Christmas cheer through every world."] = "Cada visitante de la Tierra de la Nieve, cada bola de nieve lanzada y cada muñeco de nieve hecho, envía ecos de alegría navideña a todos los mundos.",
        ["Tell me about snow and snow imps."] = "Háblame de la nieve y de los diablillos de nieve.",
        ["When your world and the Land of Snow are close, I send my snow imps to Gielinor to share the gift of snow."] = "Cuando tu mundo y la Tierra de la Nieve están cerca, envío mis diablillos de nieve a Gielinor para compartir el regalo de la nieve.",
        ["The snow my imps bring you has a little of the Land of Snow's magic... amplified by every heart the snow touches."] = "La nieve que te traen mis diablillos tiene un poco de la magia de la Tierra de la Nieve... amplificada por cada corazón que toca la nieve.",
        ["All snow that falls in other worlds is a reflection of the eternal substance of the Land of Snow."] = "Toda la nieve que cae en otros mundos es un reflejo de la sustancia eterna de la Tierra de la Nieve.",
        ["Tell me about snowmen."] = "Háblame de muñecos de nieve.",
        ["Snowmen are the eternal substance of snow, shaped into the form of man. When you build a snowman, you form an instance of a snowman in the Land of Snow; a crude and temporary copy. A vessel for an idea."] = "Los muñecos de nieve son la sustancia eterna de la nieve, con la forma del hombre. Cuando construyes un muñeco de nieve, formas un ejemplo de muñeco de nieve en la Tierra de la Nieve; una copia tosca y temporal. Un recipiente para una idea.",
        ["On Gielinor, winter is but a season in your year. When a snowman melts, its essence returns to the Land of Snow."] = "En Gielinor, el invierno no es más que una estación del año. Cuando un muñeco de nieve se derrite, su esencia regresa al País de la Nieve.",
        ["Here, winter never ends. Snow never melts. This joining of form and essence are eternal. So in the Land of Snow, snowmen are immortal."] = "Aquí el invierno nunca termina. La nieve nunca se derrite. Esta unión de forma y esencia es eterna. Por eso, en el País de la Nieve, los muñecos de nieve son inmortales.",
        ["land-of-snow"] = "tierra-de-nieve",
        ["Traditionally, the Land of Snow's midwinter celebration features a snowman tournament."] = "Tradicionalmente, la celebración de pleno invierno en la Tierra de la Nieve incluye un torneo de muñecos de nieve.",
        ["A great snow tournament, where immortal snow warriors, snow rangers and snow mages battle to see which is best."] = "Un gran torneo de nieve, donde guerreros de nieve inmortales, guardabosques de nieve y magos de nieve luchan para ver cuál es mejor.",
        ["Since each style has counter-balanced advantage against and weakness to another, the whole arrangement honours Guthix."] = "Dado que cada estilo tiene una ventaja y una debilidad contrarrestadas frente a otro, todo el arreglo honra a Guthix.",
        ["Happy Christmas, your majesty."] = "Feliz Navidad, majestad.",
        ["Happy Christmas, noble visitor."] = "Feliz Navidad, noble visitante.",
    },
    ["Quercus"] = {
        ["Hello."] = "Hola.",
        ["Hmm? Oh, pardon me, human. I was tracking the movements of warbands out in the Wilderness."] = "¿Mmm? Oh, perdóname, humano. Estaba siguiendo los movimientos de las bandas de guerra en el Wilderness.",
        ["What would you like to ask?"] = "¿Qué te gustaría preguntar?",
        ["Warbands? What do you mean?"] = "¿Bandas de guerra? ¿Qué quieres decir?",
        ["Warbands are gathering under the banners of the pretender gods, looting and hoarding, and gathering like- minded brigands to their cause."] = "Las bandas de guerreros se están reuniendo bajo los estandartes de los dioses pretendientes, saqueando y acaparando, y reuniendo bandidos con ideas afines para su causa.",
        ["They are becoming a threat to the balance of this world, and I am sending adventurers to dispatch them."] = "Se están convirtiendo en una amenaza para el equilibrio de este mundo y enviaré aventureros para despacharlos.",
        ["You look pretty tough. Couldn't you deal with them yourself?"] = "Te ves bastante duro. ¿No podrías encargarte de ellos tú mismo?",
        ["In keeping with the teachings of Guthix, I cannot intervene directly. Rather, I seek to influence events by introduction of a balancing force."] = "De acuerdo con las enseñanzas de Guthix, no puedo intervenir directamente. Más bien, busco influir en los acontecimientos mediante la introducción de una fuerza equilibradora.",
        ["I have the Sight, which allows me to cast my gaze into the Wilderness, spotting any warbands that may be gathering."] = "Tengo la Vista, que me permite mirar al Wilderness y detectar cualquier banda de guerra que pueda estar reuniéndose.",
        ["Why are these warbands gathering out in the Wilderness?"] = "¿Por qué estas bandas de guerra se están reuniendo en Wilderness?",
        ["Recently, there seems to have been a shift in the balance. There have always been outlaws bands living in the wild lands to the north. A nuisance at worst, but lately...something has changed."] = "Recientemente, parece haber habido un cambio en la balanza. Siempre ha habido bandas de forajidos viviendo en las tierras salvajes del norte. Una molestia en el peor de los casos, pero últimamente... algo ha cambiado.",
        ["They appear to have found faith."] = "Parecen haber encontrado la fe.",
        ["Faith? Perhaps that's a good thing."] = "¿Fe? Quizás eso sea algo bueno.",
        ["No! Not at all."] = "¡No! De nada.",
        ["Before, they reaved and plundered - yes - but they lacked focus and discipline, and were fettered by infighting."] = "Antes, saqueaban y saqueaban, sí, pero carecían de concentración y disciplina, y estaban encadenados por luchas internas.",
        ["Now they muster in warbands: hoarding resources; training and marshalling greater forces; committing ever- worse banditry under the banners of the pretender gods."] = "Ahora se reúnen en bandas de guerra: acaparan recursos; entrenar y reunir fuerzas mayores; cometiendo bandidaje cada vez peor bajo los estandartes de los dioses pretendientes.",
        ["Brigands and scoundrels still, but all the more dangerous for their renewed sense of purpose. Men such as these may one day endanger the balance of this world, if left unchecked."] = "Bandidos y sinvergüenzas siguen siendo, pero aún más peligrosos por su renovado sentido de propósito. Hombres como estos podrían algún día poner en peligro el equilibrio de este mundo si no se los controla.",
        ["How can I get involved?"] = "¿Cómo puedo involucrarme?",
        ["Check in with me from time to time. I shall also announce the presence of warband camps in the Wilderness worldwide. Once I have located a warband camp, it may be assailed and the supplies in its tents seized."] = "Consúltame de vez en cuando. También anunciaré la presencia de campamentos de bandas de guerra en Wilderness en todo el mundo. Una vez que haya localizado un campamento de la banda de guerra, puedo ser atacado y confiscar los suministros en sus tiendas.",
        ["So we run in and kill everyone, steal the supplies and bring them back here?"] = "¿Entonces entramos corriendo y matamos a todos, robamos los suministros y los traemos aquí?",
        ["No, no. Killing is not always the best option."] = "No, no. Matar no siempre es la mejor opción.",
        ["Allow me to explain. On arrival, the warband will be on guard and it will not be possible to loot the supply tents. If you can distract them, you'll gain an advantage and - potentially - additional rewards."] = "Permíteme explicarte. A su llegada, la banda estará en guardia y no será posible saquear las tiendas de suministros. Si puedes distraerlos, obtendrás una ventaja y, potencialmente, recompensas adicionales.",
        ["Interesting. Go on."] = "Interesante. Seguir.",
        ["Each camp centres around a summoning beam: an unstable magical node, crudely manipulated by the warband's mages to draw allies to their cause."] = "Cada campamento se centra alrededor de un rayo de invocación: un nodo mágico inestable, crudamente manipulado por los magos de la banda para atraer aliados a su causa.",
        ["If you manage to position yourself somewhere you aren't being seen - but close enough to the beam, with a clear line of sight - it should be a simple matter to shift its alignment."] = "Si logras ubicarte en algún lugar donde no te vean, pero lo suficientemente cerca del haz, con una línea de visión clara, debería ser sencillo cambiar su alineación.",
        ["Once that's done, you can use the beam again, to summon a force less...sympathetic than the warband would hope."] = "Una vez hecho esto, puedes usar el rayo nuevamente para convocar una fuerza menos... comprensiva de lo que la banda esperaría.",
        ["I see...knock the summoning beam out of whack, summon in another warband, and watch the ensuing chaos!"] = "Ya veo... ¡desequilibra el rayo de invocación, convoca a otra banda y observa el caos resultante!",
        ["I prefer to think of it as balance being restored - but yes."] = "Prefiero pensar que se trata de un restablecimiento del equilibrio, pero sí.",
        ["You will receive Prayer experience for shifting the beam, and Summoning experience for successfully summoning aid. After the battle is over, you can loot peacefully."] = "Recibirás experiencia Prayer por cambiar el rayo y experiencia Summoning por convocar ayuda con éxito. Una vez terminada la batalla, podrás saquear pacíficamente.",
        ["So I don't have to fight if I don't feel up to it?"] = "¿Entonces no tengo que pelear si no me siento con ganas?",
        ["No. If you've summoned in reinforcements they can fight for you. When the battle is over, you will be able to loot safely. It'll be quicker if you get involved though!"] = "No. Si has convocado refuerzos, ellos pueden luchar por ti. Cuando termine la batalla, podrás saquear de forma segura. ¡Sin embargo, será más rápido si te involucras!",
        ["Never forget that avarice lurks in the hearts of all men, though, and that this is the Wilderness. Be on guard for treachery from your fellow adventurers!"] = "Sin embargo, nunca olvides que la avaricia acecha en los corazones de todos los hombres y que este es el Wilderness. ¡Esté atento a la traición de sus compañeros aventureros!",
        ["So say I pull this off - I destabilise their beam, converting it to an opposing faction, then use that to summon them in, I just loot whatever I can and bring it back to you?"] = "Entonces, digamos que lo logro: desestabilizo su rayo, convirtiéndolo en una facción opuesta, luego lo uso para convocarlos, ¿simplemente saqueo todo lo que puedo y te lo devuelvo?",
        ["Yes. However, each camp will have different supplies: usually three different types from Herblore, Mining, Smithing, Construction and Farming."] = "Sí. Sin embargo, cada campamento tendrá suministros diferentes: normalmente tres tipos diferentes de Herblore, Mining, Smithing, Construction y Farming.",
        ["You can only take 25 items before the camp is empty, but which 25 items you choose to take is up to you."] = "Solo puedes tomar 25 artículos antes de que el campamento esté vacío, pero los 25 artículos que elijas tomar dependen de ti.",
        ["Be warned, though! Teleportation will not be possible while carrying the items. Even if you can get to the camp quickly, getting out may be a lot more dangerous."] = "¡Pero ten cuidado! La teletransportación no será posible mientras se lleven los artículos. Incluso si puedes llegar al campamento rápidamente, salir puede ser mucho más peligroso.",
        ["Thanks for the information."] = "Gracias por la información.",
        ["I am glad to help. Anything else?"] = "Me alegra poder ayudar. ¿Algo más?",
        ["Ask something else."] = "Pregunta algo más.",
        ["Goodbye."] = "Adiós.",
        ["Peace in balance."] = "Paz en equilibrio.",
        ["Talk about current event."] = "Habla sobre el evento actual.",
        ["I sense no camps in the Wilderness at this time. I feel there is around [hours and minutes] until the next event."] = "No veo ningún campamento en Wilderness en este momento. Siento que queda alrededor de [hours and minutes] hasta el próximo evento.",
        ["I sense no camps in the Wilderness at this time. I sense their forces gathering. They will be with us shortly - prepare yourself!"] = "No siento que no haya campamentos en Wilderness en este momento. Siento que sus fuerzas se reúnen. Estarán con nosotros en breve: ¡prepárate!",
        ["I sense a camp south of the Dark Warriors' Fortress, not far from here."] = "Siento un campamento al sur de la Fortaleza de los Guerreros Oscuros, no lejos de aquí.",
        ["I sense a camp south-east of Red Dragon Isle."] = "Siento un campamento al sureste de Red Dragon Isle.",
        ["I sense a camp east of the Lava Maze."] = "Siento un campamento al este del Laberinto de Lava.",
        ["I do not sense the presence of the summoning beam. The ritual must have failed. Be careful when you head up there."] = "No siento la presencia del rayo de invocación. El ritual debió haber fracasado. Ten cuidado cuando subas allí.",
        ["I sense that the summoning beam is still active. If you make it up to the camp alive in a timely fashion, I'm sure you'll be able to summon in a balancing force."] = "Siento que el rayo de invocación todavía está activo. Si llegas vivo al campamento a tiempo, estoy seguro de que podrás convocar una fuerza de equilibrio.",
        ["Ahh...I sense victory. Reinforcements have already been sent to the camp."] = "Ahh... Siento la victoria. Ya se han enviado refuerzos al campo.",
        ["Anything else I should know?"] = "¿Algo más que deba saber?",
        ["I see figures moving in the camp, so be wary should you choose to assault their position. However, hope of victory is still with us."] = "Veo figuras moviéndose en el campamento, así que ten cuidado si decides atacar su posición. Sin embargo, la esperanza de la victoria todavía está con nosotros.",
        ["I sense that the battle is over. The loot is safe for the taking. Well...as safe as it can be, in the Wilderness."] = "Siento que la batalla ha terminado. El botín está a salvo para tomarlo. Bueno... lo más seguro posible, en el Wilderness.",
        ["Talk about rewards."] = "Habla de recompensas.",
        ["Talk about rewards"] = "hablar de recompensas",
        ["Tell me about rewards."] = "Cuéntame sobre las recompensas.",
        ["I sense turmoil and strife on the horizon, and it would behove us all to seek a balance of powers."] = "Siento agitación y conflictos en el horizonte, y nos correspondería a todos buscar un equilibrio de poderes.",
        ["If you find the camps I sense and bring me back the materials they are hoarding, I shall reward you greatly."] = "Si encuentras los campamentos que siento y me traes los materiales que están acumulando, te recompensaré enormemente.",
        ["And I can find these rewards in the Wilderness?"] = "¿Y puedo encontrar estas recompensas en Wilderness?",
        ["Correct. I can sense the camps, but cannot intervene directly. If you are willing to do so in my place, just return here with the spoils should you make it out alive."] = "Correcto. Puedo sentir los campos, pero no puedo intervenir directamente. Si estás dispuesto a hacerlo en mi lugar, regresa aquí con el botín si logras salir con vida.",
        ["I'd like to toggle my rewards."] = "Me gustaría alternar mis recompensas.",
        ["When I defeat a player carrying supplies in the wilderness, I'd like to receive coins as a reward."] = "Cuando derrote a un jugador que lleva suministros en wilderness, me gustaría recibir coins como recompensa.",
        ["Certainly Player. Speak to me again should you wish to change this."] = "Ciertamente Player. Hable conmigo nuevamente si desea cambiar esto.",
        ["When I defeat a player carrying supplies in the wilderness, I'd like to receive their supplies as a reward."] = "Cuando derrote a un jugador que lleva suministros en wilderness, me gustaría recibir sus suministros como recompensa.",
        ["Task System"] = "Sistema de tareas",
        ["Choose an option:"] = "Elige una opción:",
        ["Tell me about the Task System."] = "Cuéntame sobre el sistema de tareas.",
        ["Very well: the Achievement System is a collection of deeds you may wish to complete while adventuring around the world."] = "Muy bien: el Sistema de Logros es una colección de hazañas que quizás desees completar mientras viajas por el mundo.",
        ["You can earn special rewards for completing certain achievements; at the very least, each is worth a cash bounty from Explorer Jack in Lumbridge."] = "Puedes ganar recompensas especiales por completar ciertos logros; como mínimo, cada uno vale una recompensa en efectivo de Explorer Jack en Lumbridge.",
        ["Some also give items that will help complete other achievements, and many count as progress towards the set for the area they're in."] = "Algunos también ofrecen elementos que ayudarán a completar otros logros y muchos cuentan como progreso hacia el conjunto del área en la que se encuentran.",
        ["Tell me about the set reward for this locality."] = "Cuéntame sobre la recompensa establecida para esta localidad.",
        ["For completing the Wilderness set, you are presented with Wilderness sword."] = "Por completar el conjunto Wilderness, se te presenta la espada Wilderness.",
        ["This sword will become increasingly useful with each difficulty level of the set that you complete."] = "Esta espada será cada vez más útil con cada nivel de dificultad del conjunto que completes.",
        ["When you are presented with your rewards, you will be told of their uses."] = "Cuando se le presenten sus recompensas, se le informará sobre sus usos.",
        ["You may also select a set Task (denoted in the main Task System interface by a small shield icon) and choose 'Rewards' to see what rewards a set item provides."] = "También puede seleccionar una tarea determinada (indicada en la interfaz principal del sistema de tareas mediante un pequeño icono de escudo) y elegir 'Recompensas' para ver qué recompensas proporciona un elemento determinado.",
        ["How do I claim these rewards?"] = "¿Cómo reclamo estas recompensas?",
        ["You need to complete all the Tasks in the set of a particular difficulty, then you can claim your reward. Most of the Wilderness set's Tasks are straightforward, although you might find some require quests to be"] = "Debes completar todas las tareas del conjunto de una dificultad particular y luego podrás reclamar tu recompensa. La mayoría de las tareas del conjunto Wilderness son sencillas, aunque es posible que algunas requieran misiones.",
        ["started, if not finished."] = "iniciado, si no terminado.",
        ["To claim the Wilderness set reward, speak to Mr Ex, Mandrith, Kolodion or myself."] = "Para reclamar la recompensa del conjunto Wilderness, habla con Mr Ex, Mandrith, Kolodion o conmigo mismo.",
        ["Sorry, I was just leaving."] = "Lo siento, me estaba yendo.",
        ["Can I claim any rewards from you?"] = "¿Puedo reclamar alguna recompensa de usted?",
        ["You don't have any more rewards to claim!"] = "¡Ya no tienes más recompensas para reclamar!",
        ["I'm afraid you don't have enough inventory space to claim all your rewards. Speak to me again when you have 3 spaces."] = "Me temo que no tienes suficiente espacio en el inventario para reclamar todas tus recompensas. Hablame de nuevo cuando tengas 3 espacios.",
        ["I've completed all the tasks in the hard Wilderness task set."] = "He completado todas las tareas del conjunto de tareas difíciles de Wilderness.",
        ["Well done Player, I've kept some rewards aside for you."] = "Bien hecho Player, he reservado algunas recompensas para ti.",
        ["[You are given some rewards for completing the hard Wilderness task set!]"] = "[¡Recibirás algunas recompensas por completar el difícil conjunto de tareas Wilderness!]",
        ["There you go, looks like that's everything."] = "Ahí lo tienes, parece que eso es todo.",
        ["I lost the Wilderness sword 3 you gave me..."] = "Perdí la espada Wilderness 3 que me diste...",
        ["Lucky for you I have a spare... I'm afraid it's going to cost you 80,000 coins though."] = "Por suerte para ti, tengo uno de repuesto... Aunque me temo que te costará 80.000 coins.",
        ["Reclaim for 80,000 coins?"] = "¿Reclamar 80.000 coins?",
        ["Yes."] = "Sí.",
        ["You can not afford that."] = "No puedes permitirte eso.",
        ["But it doesn't look like you have enough money for that. Come back to me when you do."] = "Pero no parece que tengas suficiente dinero para eso. Vuelve conmigo cuando lo hagas.",
        ["[You're handed another Wilderness sword 3.]"] = "[Te entregan otra espada Wilderness 3.]",
        ["No thanks."] = "No, gracias.",
        ["Could I buy a spare of the reward?"] = "¿Puedo comprar un repuesto de la recompensa?",
        ["Wilderness sword 1"] = "Wilderness espada 1",
        ["Wilderness sword 1? Yes, but I'm afraid it would cost you 50,000 coins."] = "Wilderness espada 1? Sí, pero me temo que te costaría 50.000 coins.",
        ["Purchase another for 50,000 coins?"] = "¿Comprar otro por 50.000 coins?",
        ["Yes"] = "si",
        ["[You're handed another Wilderness sword 1.]"] = "[Te entregan otra espada Wilderness 1.]",
        ["Wilderness sword 2"] = "Wilderness espada 2",
        ["Wilderness sword 2? Yes, but I'm afraid it would cost you 65,000 coins."] = "Wilderness espada 2? Sí, pero me temo que te costaría 65.000 coins.",
        ["Purchase another for 65,000 coins?"] = "¿Comprar otro por 65.000 coins?",
        ["[You're handed another Wilderness sword 2.]"] = "[Te entregan otra espada Wilderness 2.]",
        ["Wilderness sword 3"] = "Wilderness espada 3",
        ["Wilderness sword 3? Yes, but I'm afraid it would cost you 80,000 coins."] = "Wilderness espada 3? Sí, pero me temo que te costaría 80.000 coins.",
        ["Purchase another for 80,000 coins?"] = "¿Comprar otro por 80.000 coins?",
        ["Wilderness sword 4"] = "Wilderness espada 4",
        ["Wilderness sword 4? Yes, but I'm afraid it would cost you 100,000 coins."] = "Wilderness espada 4? Sí, pero me temo que te costaría 100.000 coins.",
        ["Purchase another for 100,000 coins?"] = "¿Comprar otro por 100.000 coins?",
        ["[You're handed another Wilderness sword 4.]"] = "[Te entregan otra espada Wilderness 4.]",
        ["Nothing, actually."] = "En realidad, nada.",
        ["Maintain the balance, Player."] = "Mantener el saldo, Player.",
        ["You don't have any items to hand in."] = "No tienes ningún artículo para entregar.",
        ["Would you like to hand in the reward items?"] = "¿Quieres entregar los artículos de recompensa?",
        ["Yes (for XP)"] = "Sí (para XP)",
        ["You have been awarded [amount] XP in [skill]!"] = "¡Has recibido [amount] XP en [skill]!",
        ["Yes (for [amount]gp)"] = "Sí (para [amount]gp)",
        ["Hand your supplies in for [amount] coins?"] = "¿Entregar sus suministros para [amount] coins?",
        ["Nevermind"] = "No importa",
        ["I see you have some materials on your person already. Would you like me to take them?"] = "Veo que ya tienes algunos materiales contigo. ¿Quieres que los lleve?",
    },
    ["Quest guide"] = {
        ["**Quest guide** Ah. Welcome, adventurer. I'm here to tell you all about quests. Let's start by opening the {{colour|blue|Quest List}}."] = "**Quest guide** Ah. Bienvenido, aventurero. Estoy aquí para contarte todo sobre las misiones. Comencemos abriendo el {{colour|blue|Quest List}}.",
        ["**Quest guide** Quests can vary greatly from collecting beads to hunting down dragons. You have to experience the thrill of questing yourself to fully understand. You may find some adventure in the cave under my house."] = "**Quest guide** Las misiones pueden variar mucho, desde recolectar cuentas hasta cazar dragones. Tienes que experimentar la emoción de buscarte a ti mismo para comprenderlo completamente. Quizás encuentres alguna aventura en la cueva debajo de mi casa.",
    },
    ["Quetzathog"] = {
        ["I was weak once. {{Audio button|Quetzathog - I was weak once.ogg}}"] = "Una vez fui débil. {{Audio button|Quetzathog - I was weak once.ogg}}",
        ["I lacked faith and thought the mwanu lost.{{Audio button|Quetzathog - I lacked faith.ogg}}"] = "Me faltó fe y pensé que el mwanu había perdido.{{Audio button|Quetzathog - I lacked faith.ogg}}",
        ["But Tezcasathla showed me a new path.{{Audio button|Quetzathog - But Tezcasathla showed me a new path.ogg}}"] = "Pero Tezcasathla me mostró un nuevo camino.{{Audio button|Quetzathog - But Tezcasathla showed me a new path.ogg}}",
        ["My world is infested, plagued by the weak and the impure.{{Audio button|Quetzathog - My world is infested.ogg}}"] = "Mi mundo está infestado, plagado de débiles e impuros.{{Audio button|Quetzathog - My world is infested.ogg}}",
        ["But soon I shall return and take back what was stolen.{{Audio button|Quetzathog - But soon I shall return.ogg}}"] = "Pero pronto regresaré y recuperaré lo robado.{{Audio button|Quetzathog - But soon I shall return.ogg}}",
        ["The mwanu will rise again.{{Audio button|Quetzathog - The mwanu will rise again.ogg}}"] = "El mwanu volverá a subir.{{Audio button|Quetzathog - The mwanu will rise again.ogg}}",
    },
    ["Quoth the Raven"] = {
        ["Offer me the first of thy master's creations and receive a gift in return."] = "Ofréceme la primera de las creaciones de tu maestro y recibe un regalo a cambio.",
        ["Offer wheel of cheese?"] = "¿Ofrecer rueda de queso?",
        ["Yes, in Raven's name."] = "Sí, en nombre de Raven.",
        ["You can activate this via the 'Titles' tab in the 'Customisations' interface."] = "Puede activar esto a través de la pestaña 'Títulos' en la interfaz 'Personalizaciones'.",
        ["No, weirdo."] = "No, raro.",
        ["Do you really think you can save them? There is an unpleasant metaphor in a scary-sounding place and this is a plot hook."] = "¿De verdad crees que puedes salvarlos? Hay una metáfora desagradable en un lugar que suena aterrador y esto es un gancho argumental.",
        ["Don't let Mod Stu create more puns. The game engine can only handle so many."] = "No dejes que Mod Stu cree más juegos de palabras. El motor del juego sólo puede manejar una cantidad limitada.",
        ["Have you considered killing all your friends? It could be a lot of fun!"] = "¿Has considerado matar a todos tus amigos? ¡Podría ser muy divertido!",
        ["Have you found all of the ravens yet and unlocked all 13 title variants?"] = "¿Ya encontraste a todos los cuervos y desbloqueaste las 13 variantes del título?",
        ["I hear Brassica Prime's voice is utterly melodious."] = "Escuché que la voz de Brassica Prime es absolutamente melodiosa.",
        ["I was thinking of adding a maze here. What do you think?"] = "Estaba pensando en agregar un laberinto aquí. ¿Qué opinas?",
        ["I'm writing a novel, you know. It's all about the best way to eat eyeballs. It's going to be a big hit."] = "Estoy escribiendo una novela, ¿sabes? Se trata de cuál es la mejor manera de comerse los globos oculares. Va a ser un gran éxito.",
        ["LORE LORE LOOOOOOORRRRRE!"] = "LORE LORE ¡LOOOOOOORRRRRE!",
        ["RITE OF PASSAGE!"] = "¡RITO DE PASO!",
        ["Universe Update v-Eh whatever. You all become bees or something. I don't know."] = "Actualización del universo v-Eh, lo que sea. Todos ustedes se convierten en abejas o algo así. No sé.",
    },
}

dialogues.all = {
    ["I don't feel comfortable helping you try on shoes when you are wielding something. Please remove what you are holding first."] = "No me siento cómodo ayudándote a probarte zapatos cuando estás empuñando algo. Primero retire lo que tiene en sus manos.",
    ["You'll have to take what you're wearing on your feet off first."] = "Primero tendrás que quitarte lo que llevas puesto.",
    ["You will need to remove anything worn on your feet and also disable any feet overrides before you can change your shoes."] = "Deberá quitarse todo lo que lleve puesto en los pies y también desactivar las anulaciones de los pies antes de poder cambiarse los zapatos.",
    ["Dialogue 1"] = "Diálogo 1",
    ["Good call!"] = "¡Buena decisión!",
    ["Dialogue 2"] = "Diálogo 2",
    ["Hey, they look great!"] = "¡Oye, se ven geniales!",
    ["Dialogue 3"] = "Diálogo 3",
    ["I think they suit you."] = "Creo que te quedan bien.",
    ["Dialogue 4"] = "Diálogo 4",
    ["Nice choice!"] = "¡Buena elección!",
    ["Thanks."] = "Gracias.",
    ["Meow, meow meow."] = "Miau, miau, miau.",
    ["Ooh, aren’t you an odd looking cat!"] = "Oh, ¿no eres un gato de aspecto extraño?",
    ["I’m not a cat."] = "No soy un gato.",
    ["But you’re talking cat, so you must be a cat. I may be old, but I ain’t slow yet."] = "Pero estás hablando de un gato, así que debes ser un gato. Puede que sea viejo, pero todavía no soy lento.",
    ["Now, I imagine a cat like you doesn’t get much attention in the romantic way. So I’m betting you’re single. Now, don’t fret, I have some lovely grandchildren that I’m sure you’d love."] = "Ahora, imagino que un gato como tú no recibe mucha atención en el sentido romántico. Así que apuesto a que estás soltero. Ahora, no te preocupes, tengo unos nietos encantadores que estoy seguro te encantarán.",
    ["They’re not much to look at. Their father was the ugliest tomcat I ever did see, but they’ve got good hearts and excellent hunting skills."] = "No hay mucho que ver. Su padre era el gato más feo que he visto en mi vida, pero tienen buen corazón y excelentes habilidades de caza.",
    ["I’ll pass, thanks."] = "Pasaré, gracias.",
    ["Pfft, suit yerself."] = "Pfft, haz lo que quieras.",
    ["*When selecting \"Talk to\" with the Quarry overseer in Ashdale, he will produce one of the following overhead dialogue at random, accompanied by a matching voice-over.*"] = "*Al seleccionar \"Hablar con\" con Quarry overseer en Ashdale, producirá uno de los siguientes diálogos generales al azar, acompañado de una voz en off correspondiente.*",
    ["Select an Option"] = "Seleccione una opción",
    ["What's going on here?"] = "¿Qué está pasando aquí?",
    ["Well, the short version is that the gods Marimbo and Brassica Prime, and the Godless, had a big contest fight-party near Lumbridge. They're gone now, but the dungeon they created is still around."] = "Bueno, la versión corta es que los dioses Marimbo y Brassica Prime, y los Godless, tuvieron una gran pelea de competencia cerca de Lumbridge. Ya no están, pero la mazmorra que crearon todavía existe.",
    ["You can take this tunnel there and pick up trophies while avoiding traps and guards, and earn rewards for it."] = "Puedes llevar este túnel hasta allí y recoger trofeos mientras evitas trampas y guardias, y ganar recompensas por ello.",
    ["What's the long version?"] = "¿Cuál es la versión larga?",
    ["Well, it seems that Marimbo and Brassica Prime saw the recent fighting between the other gods and decided to join in."] = "Bueno, parece que Marimbo y Brassica Prime vieron la reciente pelea entre los otros dioses y decidieron unirse.",
    ["I don't think they quite saw it as a fight, though. Marimbo knocked back banana daiquiris like it was going out of style, and Brassica Prime was acting like it was some sort of popularity contest."] = "Aunque no creo que lo vieran como una pelea. Marimbo bebió daiquiris de plátano como si estuviera pasando de moda, y Brassica Prime actuaba como si fuera una especie de concurso de popularidad.",
    ["The Godless were in on it too - Holstein and Kara-Meir, although it didn't work out well for her - but they couldn't stop Brassica winning the 'fight'."] = "Los Godless también estuvieron involucrados, Holstein y Kara-Meir, aunque no funcionó bien para ella, pero no pudieron evitar que Brassica ganara la 'pelea'.",
    ["The two gods said something I didn't quite catch, and that big stone plinth just sank into the ground. Now there's a doorway there. Never knew there was a dungeon under these fields."] = "Los dos dioses dijeron algo que no entendí del todo, y ese gran pedestal de piedra simplemente se hundió en el suelo. Ahora hay una puerta allí. Nunca supe que había una mazmorra debajo de estos campos.",
    ["And it's crazy in there! The walls move around and there's fire and monkeys and cabbages and..."] = "¡Y es una locura ahí dentro! Las paredes se mueven y hay fuego y monos y coles y...",
    ["The farmer takes a deep breath."] = "El granjero respira profundamente.",
    ["...and I'll just stay out of there, thanks. The gods had me dishing out rewards, so I suppose that's my sacred calling now."] = "...y me quedaré fuera de ahí, gracias. Los dioses me hicieron repartir recompensas, así que supongo que ahora esa es mi vocación sagrada.",
    ["I own a couple of fields around these parts, right? So there I am checking on the broccoli one day when Marimbo comes plummeting out of the sky holding a big, plump, green cabbage in one hand."] = "Soy dueño de un par de campos por aquí, ¿verdad? Así que ahí estaba, revisando el brócoli un día cuando Marimbo cae del cielo sosteniendo un repollo verde, grande y regordete en una mano.",
    ["Bless me if the cabbage doesn't begin to speak - says my 'devotion to his people has been noted' and I'm to be 'blessed over all other non-cabbages'. And then the ape pipes up and says I look near enough like one of hers, too."] = "Bendíceme si el repollo no empieza a hablar - dice que mi 'devoción a su pueblo ha sido notada' y seré 'bendecido sobre todos los demás que no son repollos'. Y luego el simio interviene y dice que yo también me parezco bastante a uno de ella.",
    ["I don't know if I like what she was implying."] = "No sé si me gusta lo que estaba insinuando.",
    ["Anyway, she picks me up in the other hand and she jumps about a mile in the air and comes down right here. The rest of it you know."] = "De todos modos, ella me levanta con la otra mano, salta aproximadamente una milla en el aire y cae justo aquí. El resto ya lo sabes.",
    ["So I suppose I'm some sort of priest of Brassica Prime now. Or of Marimbo? Maybe both."] = "Así que supongo que ahora soy una especie de sacerdote de Brassica Prime. ¿O de Marimbo? Quizás ambos.",
    ["I should get a big priesty hat."] = "Debería conseguir un sombrero sacerdotal grande.",
    ["I had other questions."] = "Tenía otras preguntas.",
    ["How do I get involved?"] = "¿Cómo me involucro?",
    ["You're supposed to run back and forth through this arena they've set up and get the highest score you can."] = "Se supone que debes correr de un lado a otro a través de esta arena que han configurado y obtener la puntuación más alta que puedas.",
    ["It's in an underground dungeony sort of place. There's things you can pick up off the ground, and little monkeys you're supposed to punch in the face."] = "Está en una especie de mazmorra subterránea. Hay cosas que puedes recoger del suelo y pequeños monos a los que se supone que debes golpear en the face.",
    ["There's also flames and big gorillas who'll try to punch you in the face. Try not to get punched in the face or burned."] = "También hay llamas y grandes gorilas que intentarán golpearte en the face. Intenta que no te golpeen en the face ni te quemes.",
    ["There's a safe spot at each end where the gorillas can't get you, but they swap back and forth. You'll see a time running after they swap ends."] = "Hay un lugar seguro en cada extremo donde los gorilas no pueden atraparte, pero cambian de un lado a otro. Verás un tiempo corriendo después de que intercambien los extremos.",
    ["Make sure you get to the other end before the timer runs out."] = "Asegúrate de llegar al otro extremo antes de que se acabe el tiempo.",
    ["How does scoring work?"] = "¿Cómo funciona la puntuación?",
    ["Every time you cross the dungeon you'll get some points. Every trophy you pick up along the way off the ground or by punching little monkeys is also worth points."] = "Cada vez que cruces la mazmorra obtendrás algunos puntos. Cada trofeo que recojas en el camino desde el suelo o golpeando a pequeños monos también vale puntos.",
    ["The longer you survive the higher you'll score. And points mean prizes!"] = "Cuanto más sobrevivas, mayor puntuación obtendrás. ¡Y los puntos significan premios!",
    ["What happens if I get knocked out?"] = "¿Qué pasa si me noquean?",
    ["You turn into a gorilla."] = "Te conviertes en un gorila.",
    ["No, seriously. I've seen it happen. Anyone who gets caught outside the safe spot when the timer runs out, or who runs out of heath by being punched or burned or whatever, swells up and goes all hairy."] = "No, en serio. Lo he visto suceder. Cualquiera que quede atrapado fuera del lugar seguro cuando se acaba el tiempo, o que se quede sin salud al recibir un puñetazo, quemarse o lo que sea, se hincha y se pone peludo.",
    ["It's only temporary! Once you come out of the dungeon you're fine again. And while you're a gorilla you get to punch people in the face and that'll get you trophies too, so it's not all bad."] = "¡Es sólo temporal! Una vez que salgas del calabozo estarás bien otra vez. Y mientras eres un gorila, puedes golpear a la gente en the face y eso también te dará trofeos, así que no es del todo malo.",
    ["Tell me about abilities."] = "Háblame de habilidades.",
    ["People can do all sorts of weird stuff down there. I've seen folks walk through walls of fire without flinching, and pick up stuff from metres away without any runes at all."] = "La gente puede hacer todo tipo de cosas raras ahí abajo. He visto gente caminar a través de paredes de fuego sin inmutarse y recoger cosas a metros de distancia sin ninguna runa.",
    ["You can bring one passive and two active abilities into the game, which grant you various advantages. Click on an active ability in the minigame bar to use it during a game. Different abilities have different cooldowns."] = "Puedes incorporar al juego una habilidad pasiva y dos activas, que te otorgan varias ventajas. Haz clic en una habilidad activa en la barra de minijuegos para usarla durante un juego. Diferentes habilidades tienen diferentes tiempos de reutilización.",
    ["What's in it for me?"] = "¿Qué gano yo con esto?",
    ["You can earn experience in several skills, there are items you can buy which help with farming or slayer, and you can unlock new abilities to use in the arena downstairs."] = "Puedes ganar experiencia en varias habilidades, hay artículos que puedes comprar que te ayudarán con la agricultura o el cazador, y puedes desbloquear nuevas habilidades para usar en la arena de abajo.",
    ["Tell me about the reward items."] = "Cuéntame sobre los artículos de recompensa.",
    ["There's three of 'em. The seedicide destroys farming seeds that would drop from monsters you kill, turning them into a chunk of farming experience. You can set what seeds it's allowed to eat."] = "Son tres. El seedicida destruye las semillas agrícolas que caerían de los monstruos que matas, convirtiéndolas en una gran experiencia agrícola. Puedes establecer qué semillas se permite comer.",
    ["The slayer VIP tickets let you choose between two options when you're picking up a new slayer task - there'll be the usual choice as a default, and an alternative you can ask for instead."] = "Los boletos VIP de cazador te permiten elegir entre dos opciones cuando eliges una nueva tarea de cazador: habrá la opción habitual por defecto y una alternativa que puedes solicitar en su lugar.",
    ["The patch bomb is a handy time-saving device! use it on a farming patch and it'll check the health of, harvest, chop down and clear anything that's in it in a single swoop, cleaving it clear for new seeds."] = "¡La bomba parche es un práctico dispositivo para ahorrar tiempo! Úselo en un terreno agrícola y verificará la salud, cosechará, cortará y limpiará todo lo que haya en él de una sola vez, partiéndolo para obtener nuevas semillas.",
    ["Tell me about unlocking abilities."] = "Cuéntame sobre cómo desbloquear habilidades.",
    ["There's a bunch of abilities you can't just use right off the bat, I can sell you unlocks for 'em. Once you've unlocked them, they're yours to use as you want."] = "Hay un montón de habilidades que no puedes usar de inmediato, puedo venderte desbloqueos para ellas. Una vez que los hayas desbloqueado, podrás usarlos como quieras.",
    ["I'd like to manage my abilities and rewards."] = "Me gustaría gestionar mis habilidades y recompensas.",
    ["I'd like to buy rewards."] = "Me gustaría comprar recompensas.",
    ["I'd like to adjust my equipped abilities."] = "Me gustaría ajustar mis habilidades equipadas.",
    ["Actually, I had some questions."] = "En realidad, tenía algunas preguntas.",
    ["Please, tell me... Is there really a gorilla god and a talking cabbage, or was it me drinking all the banana daiquiris?"] = "Por favor, dígame... ¿Existe realmente un dios gorila y un repollo parlante, o fui yo bebiendo todos los daiquiris de plátano?",
    ["No, no...they're real...that happened. But it's okay, they've gone now. You can rest easy."] = "No, no... son reales... eso pasó. Pero está bien, ya se han ido. Puedes estar tranquilo.",
    ["C-can I go back to tending my fields, then?"] = "¿P-puedo volver a cuidar mis campos, entonces?",
    ["Yes, my friend. Go back to your fields."] = "Sí, amigo mío. Vuelve a tus campos.",
    ["I'll Never Get Tired of Cabbage Water"] = "Nunca me cansaré del agua de repollo",
    ["Talk to Vannaka the Slayer Master outside Edgeville dungeon, south of Edgeville."] = "Habla con Vannaka y Slayer Master fuera de la mazmorra Edgeville, al sur de Edgeville.",
    ["Oh, thank you!"] = "¡Oh, gracias!",
    ["Looks like I've completed everything. I'd better go and see Hans about that reward!"] = "Parece que he completado todo. ¡Será mejor que vaya a ver a Hans sobre esa recompensa!",
    ["Short version is, the gods are having people run around in a dungeon full of troops and monkeys, picking up trophies, as some sort of contest. Or maybe some sort of party."] = "La versión corta es que los dioses están haciendo que la gente corra en una mazmorra llena de tropas y monos, recogiendo trofeos, como una especie de concurso. O tal vez algún tipo de fiesta.",
    ["They and that Godless fellow are recruiting people to join in on their behalf, in return for rewards."] = "Ellos y ese tipo impío están reclutando personas para que se unan en su nombre, a cambio de recompensas.",
    ["Well, it seems that Marimbo and Brassica Prime, that's them over there on the fancy thrones -saw the recent fighting between the other gods."] = "Bueno, parece que Marimbo y Brassica Prime, que están allí en los elegantes tronos, vieron la reciente pelea entre los otros dioses.",
    ["I don't think they quite see it as a fight, though. Marimbo's knocking back banana daiquiris like it's going out of style, and Brassica Prime's acting like it's some sort of popularity contest."] = "Aunque no creo que lo vean como una pelea. Marimbo está tomando daiquiris de plátano como si estuviera pasando de moda, y Brassica Prime está actuando como si fuera una especie de concurso de popularidad.",
    ["Then Holstein and Kara-Meir turned up - I'll let him tell that tale, though. Anyway, he's got in on it all too."] = "Entonces aparecieron Holstein y Kara-Meir. Aunque dejaré que él cuente esa historia. De todos modos, él también participa en todo esto.",
    ["...and I'll just stay out of there, thanks. They've got me taking names, and dishing out rewards, for people who join in."] = "...y me quedaré fuera de ahí, gracias. Me tienen tomando nombres y repartiendo recompensas a las personas que se unen.",
    ["How long's it all going on for?"] = "¿Cuánto tiempo dura todo esto?",
    ["Two weeks, they said they'd be here. Don't reckon either of them has the attention span for much more than that, if I'm honest."] = "Dos semanas, dijeron que estarían aquí. No creo que ninguno de ellos tenga capacidad de atención para mucho más que eso, si soy honesto.",
    ["I don't know what they think they're getting out of it. There's none of that green glowy energy stuff left under Lumbridge any more, Saradomin and Zamorak used it all up."] = "No sé qué creen que están obteniendo con esto. Ya no queda nada de esa energía verde brillante bajo Lumbridge, Saradomin y Zamorak la usaron toda.",
    ["But you can bet your life they're not going to think to clean up after themselves when they go. Not seen that sort of politeness from gods."] = "Pero puedes apostar tu vida a que no pensarán en limpiar lo que ensucien cuando se vayan. No he visto ese tipo de cortesía por parte de los dioses.",
    ["How'd you get roped into this?"] = "¿Cómo te involucraste en esto?",
    ["Well, they're having a sort of contest right now. So you tell me what side you're on - maybe talk to them about it first to see which you like better -then you get in the ring there."] = "Bueno, ahora mismo están teniendo una especie de concurso. Así que dime de qué lado estás, tal vez hables con ellos primero para ver cuál te gusta más, y luego te subes al ring.",
    ["The longer you survive the higher you'll score. And points mean prizes! Also glory to your faction, if that rotates your millwheel."] = "Cuanto más sobrevivas, mayor puntuación obtendrás. ¡Y los puntos significan premios! También gloria a tu facción, si eso hace girar tu rueda de molino.",
    ["Well, obviously the glory of supporting your chosen faction is the..."] = "Bueno, obviamente la gloria de apoyar a la facción elegida es...",
    ["...hahaha! No, sorry, couldn't keep a straight face. It's all about the rewards!"] = "...¡jajaja! No, lo siento, no pude mantener la cara seria. ¡Se trata de las recompensas!",
    ["During these two weeks, you can also buy a cape to show off your dedication to your faction."] = "Durante estas dos semanas, también podrás comprar una capa para mostrar tu dedicación a tu facción.",
    ["The farmer looks shifty."] = "El granjero parece sospechoso.",
    ["I'll even let you buy the other capes once you've got your own faction's, because hey! Why not?"] = "Incluso te dejaré comprar las otras capas una vez que tengas tu propia facción, porque ¡oye! ¿Por qué no?",
    ["Tell me about reward items."] = "Cuéntame sobre los artículos de recompensa.",
    ["As the contest goes on I'll let you buy more abilities - check back on day 4 and day 10."] = "A medida que avance el concurso, te dejaré comprar más habilidades. Vuelve a consultar los días 4 y 10.",
    ["I'd like to change my faction."] = "Me gustaría cambiar de facción.",
    ["How would you like to switch sides?"] = "¿Cómo le gustaría cambiar de bando?",
    ["The Godless"] = "Los impíos",
    ["Good day to you! How may I assist?"] = "¡Buenos días! ¿Cómo puedo ayudar?",
    ["Choose an option:"] = "Elige una opción:",
    ["What do you do here?"] = "¿Qué haces aquí?",
    ["I'm the quartermaster for your clan. I keep track of the jobs you or your clanmates have marked to be undertaken within the citadel; the resources it will take; and whether you can meet that requirement."] = "Soy el intendente de tu clan. Llevo un registro de los trabajos que tú o tus compañeros de clan habéis marcado para realizar dentro de la ciudadela; los recursos que se necesitarán; y si puede cumplir con ese requisito.",
    ["I am also capable of altering the day on which your buildings are altered and the resources used up, and I can award bonus experience."] = "También soy capaz de alterar el día en el que se modifican tus edificios y los recursos utilizados, y puedo otorgar experiencia adicional.",
    ["Tell me more about the job list."] = "Cuéntame más sobre la lista de trabajos.",
    ["On the job list you will see all downgrades, upkeep dues, and upgrade requests pending for your clan's citadel. Upkeep jobs will remain as long as you have a building in your citadel requiring upkeep; the others are removed when they are carried out."] = "En la lista de trabajos verás todas las solicitudes de degradación, cuotas de mantenimiento y mejoras pendientes para la ciudadela de tu clan. Los trabajos de mantenimiento permanecerán mientras tengas un edificio en tu ciudadela que requiera mantenimiento; los demás se eliminan cuando se llevan a cabo.",
    ["You may click on jobs in the list to view more information regarding their costs, and the resources available to perform those jobs, and any warnings related to jobs which currently have shortfall or unmet requirements."] = "Puede hacer clic en los trabajos de la lista para ver más información sobre sus costos y los recursos disponibles para realizar esos trabajos, y cualquier advertencia relacionada con trabajos que actualmente tienen requisitos insuficientes o no cumplidos.",
    ["If you have the requisite access permissions from your clan's officers, you may alter the list by dragging jobs to reorder them, or to cancel downgrade or upgrade jobs."] = "Si tienes los permisos de acceso necesarios de los oficiales de tu clan, puedes modificar la lista arrastrando trabajos para reordenarlos o cancelar trabajos de degradación o mejora.",
    ["You may also jump from upgrade jobs to the build interface to make alterations if need be, but that's more the artisan's area than mine, quite frankly."] = "También puedes pasar de los trabajos de actualización a la interfaz de construcción para realizar modificaciones si es necesario, pero, francamente, esa es más área del artesano que mía.",
    ["Would you like to open the list now?"] = "¿Quieres abrir la lista ahora?",
    ["Yes"] = "si",
    ["*(Job list interface opens)*"] = "*(Se abre la interfaz de lista de trabajos)*",
    ["Tell me about moving the build tick."] = "Cuéntame cómo mover el tick de compilación.",
    ["The owner, deputy or overseer of a clan may move the build tick to a day of the week and time of day more suitable for your clan's activity. Just talk to me about it and I will set your build tick to be due precisely one week from that moment."] = "El propietario, diputado o supervisor de un clan puede mover la marca de construcción a un día de la semana y a una hora del día más adecuada para la actividad de su clan. Sólo háblame al respecto y configuraré tu tick de compilación para que venza exactamente una semana a partir de ese momento.",
    ["I must warn you, though, that it will cost you a week's upkeep up front to do so. You will be allowed to do it only once per week and you may not move the tick to the same day on which it already falls."] = "Debo advertirle, sin embargo, que hacerlo le costará una semana de mantenimiento por adelantado. Se te permitirá hacerlo sólo una vez por semana y no podrás mover la garrapata al mismo día en el que ya cae.",
    ["Moving the build tick will also not carry out any upgrade or downgrade jobs you have listed."] = "Mover la marca de compilación tampoco llevará a cabo ningún trabajo de actualización o degradación que hayas enumerado.",
    ["Do you wish to move the build tick?"] = "¿Desea mover el tick de compilación?",
    ["Your rank is not high enough to move your clan's build/upkeep day."] = "Tu rango no es lo suficientemente alto como para cambiar el día de construcción/mantenimiento de tu clan.",
    ["About experience boosts..."] = "Acerca de los aumentos de experiencia...",
    ["I'm afraid I've given you experience rather recently, and as you're new to the clan I can't give you more for at least another day."] = "Me temo que te he dado experiencia hace poco y como eres nuevo en el clan no puedo darte más hasta al menos hasta dentro de un día.",
    ["I've already given you some experience; I won't be able to give you more until after the next build cycle."] = "Ya te he dado algo de experiencia; No podré darte más hasta después del próximo ciclo de construcción.",
    ["Can you give me some experience?"] = "¿Puedes darme alguna experiencia?",
    ["As you work for your clan, gathering resources we need for building and maintaining the Stronghold, you will make progress towards earning an experience boost. You will be able to use up the bonus experience both here in the citadel and out in the rest of the world."] = "A medida que trabajes para tu clan, reuniendo los recursos que necesitamos para construir y mantener la Fortaleza, progresarás para obtener un aumento de experiencia. Podrás utilizar la experiencia adicional tanto aquí en la ciudadela como en el resto del mundo.",
    ["I must warn you that I can only provide one bonus per week."] = "Debo advertirles que solo puedo ofrecer un bono por semana.",
    ["Now, let's see..."] = "Ahora, veamos...",
    ["Our records show that you have done no work for us this week."] = "Nuestros registros muestran que no ha trabajado para nosotros esta semana.",
    ["Yes; you've done enough work to earn experience. Which skill would you like it in?"] = "Sí; has trabajado suficiente para ganar experiencia. ¿En qué habilidad te gustaría hacerlo?",
    ["How can I earn bonus experience?"] = "¿Cómo puedo ganar experiencia extra?",
    ["Earning the boost is simply a matter of working in any of our resource-gathering buildings, from the Woodcutting tree up to the Summoning grove. Once you've gathered enough, spread however you wish between the plots available to the clan, I can grant you the bonus."] = "Obtener el impulso es simplemente cuestión de trabajar en cualquiera de nuestros edificios de recolección de recursos, desde el árbol Woodcutting hasta la arboleda Summoning. Una vez que hayas reunido lo suficiente, reparte como quieras entre las parcelas disponibles para el clan, puedo otorgarte el bono.",
    ["I'm here for an experience boost"] = "Estoy aquí para un impulso de experiencia.",
    ["I'm terribly sorry. You'll need to do more work before I can give you experience."] = "Lo siento mucho. Necesitarás trabajar más antes de que pueda brindarte experiencia.",
    ["I'd like to check the Job list."] = "Me gustaría consultar la lista de trabajos.",
    ["I'd like to move the Clan's build tick."] = "Me gustaría mover el tick de construcción del clan.",
    ["About bonus experience..."] = "Acerca de la experiencia adicional...",
    ["Can you sell me some Clan Citadel Boosters?"] = "¿Puedes venderme algunos potenciadores de la Ciudadela del clan?",
    ["Of course! How many do you want?"] = "¡Por supuesto! ¿Cuantos quieres?",
    ["How many would you like to buy?"] = "¿Cuántos te gustaría comprar?",
    ["One."] = "Uno.",
    ["Three."] = "Tres.",
    ["Six."] = "Seis.",
    ["None, I changed my mind."] = "Ninguno, cambié de opinión.",
    ["Good day [Sir/Miss]. I'm the quartermaster for King Tyras's camp. We have a little we could trade here. We have a new stock of dragon halberds. Would you like a look at what we have now?"] = "Buenos días [Sir/Miss]. Soy el intendente del campamento del rey Tyras. Tenemos un poco que podríamos intercambiar aquí. Disponemos de un nuevo stock de alabardas de dragón. ¿Quieres ver lo que tenemos ahora?",
    ["Select an option"] = "Selecciona una opción",
    ["Yes please. What are you selling?"] = "Sí por favor. ¿Qué estás vendiendo?",
    ["No thanks."] = "No, gracias.",
    ["Are ye ready to set sail for the Arc, Cap'n?"] = "¿Está listo para zarpar hacia el Arco, Capitán?",
    ["Where would you suggest we go first?"] = "¿Dónde sugieres que vayamos primero?",
    ["Hmm, that'd have to be Waiko. It's the main hub of where east meets west."] = "Hmm, ese tendría que ser Waiko. Es el centro principal donde el este se encuentra con el oeste.",
    ["Jed would no doubt have stopped there to stock up on supplies."] = "Jed sin duda se habría detenido allí para abastecerse de suministros.",
    ["Very good, Gully. Let's set sail!"] = "Muy bien, Gully. ¡Zarpemos!",
    ["Ready to sail whenever you are, cap'n."] = "Listo para navegar cuando usted lo desee, capitán.",
    ["*(The Arc interface opens.)*"] = "*(Se abre la interfaz de Arc.)*",
    ["Cap'n. I'll stock up the ship from the market. We'll be ready to set sail again whenever you're ready."] = "Capitán. Abasteceré el barco en el mercado. Estaremos listos para zarpar nuevamente cuando usted esté listo.",
    ["Gully, do you mind if I ask, what's going on with your hat?"] = "Gully, ¿te importa si te pregunto qué está pasando con tu sombrero?",
    ["It's a septicorn, Cap'n."] = "Es un septicornio, Capitán.",
    ["I thought tricorns were the fashion."] = "Pensé que los tricornios estaban de moda.",
    ["Aye, if you're just aiming for 'sailor', but I like to go the extra nautical mile! And septicorns are more than twice as good as tricorns {{nbsp}}that's math!"] = "Sí, si solo buscas ser 'marinero', ¡pero a mí me gusta hacer un esfuerzo náutico adicional! Y los septicornio son más del doble de buenos que los tricornio {{nbsp}} ¡Eso es matemática!",
    ["Calm down, Steven. You're not having any fish, you get fed too much as it is."] = "Cálmate, Steven. No comes pescado, te alimentan demasiado.",
    ["And I do wish you'd stop 'dropping feathers' down the back of my coat."] = "Y desearía que dejaras de \"dejar caer plumas\" por la parte de atrás de mi abrigo.",
    ["Wow, your seagull actually drops feathers?"] = "Vaya, ¿a tu gaviota se le caen plumas?",
    ["Er, no. It's a euphemism."] = "Eh, no. Es un eufemismo.",
    ["They ain't feathers."] = "No son plumas.",
    ["It's poop."] = "Es caca.",
    ["Yes, I got that, thank you."] = "Sí, lo entendí, gracias.",
    ["So, Gully, what's the deal with you, shall we say, over-embellishing the whole pirate thing?"] = "Entonces, Gully, ¿qué te pasa, digamos, embelleciendo demasiado todo el asunto de los piratas?",
    ["What do you mean, Cap'n?"] = "¿Qué quiere decir, Capitán?",
    ["The overwrought hat, the outfit, the what can only be described as a mega-hook, all the pirate trimmings the...seagull?"] = "El sombrero sobrecargado, el traje, lo que sólo puede describirse como un megagancho, todos los adornos piratas, ¿la gaviota?",
    ["The seagull."] = "La gaviota.",
    ["The seagull is called Steven."] = "La gaviota se llama Steven.",
    ["Okay, and...Steven."] = "Está bien, y... Steven.",
    ["I'm the most piratically piratey pirate you ever did see. There's no mistaking the very piratical nature of my pirate-ness."] = "Soy el pirata más pirata que jamás hayas visto. No hay duda de la naturaleza pirata de mi piratería.",
    ["If you cut me to my core it'd say 'pirate' through the middle."] = "Si me cortas hasta la médula, diría \"pirata\" en el medio.",
    ["Well, sure, but now I just have completely different questions."] = "Bueno, claro, pero ahora tengo preguntas completamente diferentes.",
    ["This here be the land of giants, Cap'n. Tread carefully, lest you be stepped upon."] = "Ésta es la tierra de los gigantes, Capitán. Andad con cuidado, no sea que os pisoteen.",
    ["Ah, now this be more to the taste of Steven and meself. I hear there's a colony of gnomes on this sunny island, and they brew a particularly potent rum from sweet local berries."] = "Ah, ahora esto será más del gusto de Steven y mío. He oído que hay una colonia de gnomos en esta isla soleada y elaboran un ron particularmente potente del dulce local berries.",
    ["This here be the Islands That Once Were Turtles, mate. There's a chill to this place that shivers me down to my very timbers."] = "Estas son las islas que alguna vez fueron tortugas, amigo. Hay un escalofrío en este lugar que me estremece hasta las entrañas.",
    ["You're trying mighty hard to talk like a pirate, Mister Gully. Almost too hard."] = "Está intentando con todas sus fuerzas hablar como un pirata, señor Gully. Casi demasiado duro.",
    ["Aye."] = "Sí.",
    ["I'd still rather we didn't linger here, Cap'n. Watch yourself."] = "Aún así preferiría que no nos quedáramos aquí, Capitán. Mírate a ti mismo.",
    ["The city of Gongdung be a tomb, Cap'n. A sealed tomb."] = "La ciudad de Gongdung será una tumba, Capitán. Una tumba sellada.",
    ["There ain't no treasure to be found here...only the dead, or worse. Let's be away."] = "No se puede encontrar ningún tesoro aquí... sólo los muertos, o algo peor. Vámonos lejos.",
    ["I'm not sure about this, Cap'n. Somethin' 'bout this place feels off..."] = "No estoy seguro de esto, Capitán. Algo en este lugar se siente mal...",
    ["An' if you need something more specific, I don't trust that Wadud fella."] = "Y si necesitas algo más específico, no confío en ese tipo Wadud.",
    ["He's bin by a few times since we anchored, and each time he's bin eyeing up the Revenge."] = "Ha pasado varias veces desde que anclamos, y cada vez está mirando el Revenge.",
    ["Aye, Steven. If he tries anything, go fer his eyes."] = "Sí, Steven. Si intenta algo, ve por sus ojos.",
    ["I see ye have a treasure map there, cap'n - would you like to sail to that uncharted region?"] = "Veo que tiene un mapa del tesoro allí, capitán. ¿Le gustaría navegar a esa región inexplorada?",
    ["Sail to treasure island?"] = "¿Navegar a la isla del tesoro?",
    ["Yes."] = "Sí.",
    ["Where would you like to sail?"] = "¿Dónde te gustaría navegar?",
    ["Milky Bay"] = "Bahía Láctea",
    ["The Goon Docks"] = "Los muelles del matón",
    ["Christmas Island"] = "Isla de Navidad",
    ["Springbreak Island"] = "Isla de vacaciones de primavera",
    ["Cannonball Run"] = "Carrera de bala de cañón",
    ["The Hamlet"] = "la aldea",
    ["Quis-land"] = "tierra de quis",
    ["Agar Atoll"] = "Atolón de Agar",
    ["I see ye have a map to a remote uncharted island there, cap'n - would you like to sail there? It won't even cost us any supplies!"] = "Veo que tiene un mapa de una isla remota e inexplorada, capitán. ¿Le gustaría navegar allí? ¡Ni siquiera nos costará suministros!",
    ["Sail to Uncharted Island?"] = "¿Navegar a la isla inexplorada?",
    ["*(Player is taken to uncharted island.)*"] = "*(Player es llevado a una isla inexplorada.)*",
    ["I see ye have one of those special maps to a remote uncharted island there, cap'n - I hear these islands are full of resources, would you like to sail there? It won't even cost us any supplies!"] = "Veo que tiene uno de esos mapas especiales de una isla remota e inexplorada, capitán. He oído que estas islas están llenas de recursos, ¿le gustaría navegar allí? ¡Ni siquiera nos costará suministros!",
    ["[You spot a bee and find 100 Nectar!]"] = "[¡Ves una abeja y encuentras 100 néctar!]",
    ["[You spot another bee and collect 100 Nectar!]"] = "[¡Ves otra abeja y recolectas 100 néctar!]",
    ["I wonder if this has anything to do with the person that just arrived in Falador?"] = "Me pregunto si esto tiene algo que ver con la persona que acaba de llegar a Falador.",
    ["I've already spotted this {{Sic|Bee}}!"] = "¡Ya vi este {{Sic|Bee}}!",
    ["I've already found all of the bees!"] = "¡Ya encontré todas las abejas!",
    ["What an awesome bee!"] = "¡Qué abeja tan increíble!",
    ["Hello."] = "Hola.",
    ["Er...Hello, Your Majesty."] = "Er... Hola, Su Majestad.",
    ["Have you come for a particular reason? I am a busy Queen, you know. I had to attend the opening of a new orphanage this morning."] = "¿Has venido por algún motivo en particular? Soy una reina ocupada, ¿sabes? Esta mañana tuve que asistir a la inauguración de un nuevo orfanato.",
    ["Yes, I..."] = "Sí, yo...",
    ["And this afternoon I shall be receiving the Embassador of Karamja and accompanying him on his week-long tour of Etceteria."] = "Y esta tarde recibiré al Embajador de Karamja y lo acompañaré en su gira de una semana por Etceteria.",
    ["Er, I..."] = "Eh, yo...",
    ["Then this evening we shall be putting on a grand ball! All of the kingdom's nobility will be present!"] = "¡Entonces esta noche organizaremos un gran baile! ¡Toda la nobleza del reino estará presente!",
    ["If I m..."] = "Si yo...",
    ["Oh, who am I kidding...nothing ever happens here. I always wanted to be a princess when I was a girl. If I'd been told it would be like this, I wouldn't have bothered."] = "Oh, ¿a quién engaño? Aquí nunca pasa nada. Siempre quise ser princesa cuando era niña. Si me hubieran dicho que sería así, no me habría molestado.",
    ["Your Majesty!"] = "¡Su Majestad!",
    ["Yes? Did you want something?"] = "¿Sí? ¿Querías algo?",
    ["...actually, no."] = "...en realidad, no.",
    ["Thank you for all your help, [Fremennik Name]. It's good to know that the Regent of Miscellania is willing to help his neighbours."] = "Gracias por toda tu ayuda, [Fremennik Name]. Es bueno saber que el Regente de Miscellania está dispuesto a ayudar a sus vecinos.",
    ["You're welcome, Your Majesty."] = "De nada, Su Majestad.",
    ["Thank you for everything, [Fremennik name]. It was hard to move out of my beloved castle, but worth it to be with my husband."] = "Gracias por todo, [Fremennik name]. Fue difícil mudarme de mi querido castillo, pero valió la pena estar con mi marido.",
    ["Ah, this puzzle is yours, I take it?"] = "Ah, este rompecabezas es tuyo, ¿lo entiendo?",
    ["[Queen Sigrid has given you a puzzle box!]"] = "[¡Queen Sigrid te ha regalado una caja de rompecabezas!]",
    ["Is that the best you can do? Try harder!"] = "¿Es eso lo mejor que puedes hacer? ¡Esfuérzate más!",
    ["[Queen Sigrid has given you another clue scroll!]"] = "[¡Queen Sigrid te ha dado otro pergamino de pistas!]",
    ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
    ["Great; there is the reward."] = "Genial; ahí está la recompensa.",
    ["The snow tournament draws to a close. I look forward to seeing you again next Wintumber, noble traveller!"] = "El torneo de nieve llega a su fin. ¡Espero volver a verte el próximo Wintumber, noble viajero!",
    ["Thank you for helping me enjoy the 'great' snow tournament for what it is, and take the festivities less seriously."] = "Gracias por ayudarme a disfrutar del 'gran' torneo de nieve tal como es y a tomarme las festividades menos en serio.",
    ["Who are you?"] = "¿Quién eres?",
    ["I am the Queen of Snow. The all-wise Guthix placed me in command of the forces of snow and ice that dominate the winter of each year."] = "Yo soy el Queen of Snow. El omnisciente Guthix me puso al mando de las fuerzas de la nieve y el hielo que dominan el invierno de cada año.",
    ["To what extent, as monarch of this land, I remain my mother's daughter and successor to my sister is an interesting philosophical question."] = "Hasta qué punto, como monarca de esta tierra, sigo siendo hija de mi madre y sucesora de mi hermana es una cuestión filosófica interesante.",
    ["Does the head fit the crown or the crown fit the head?"] = "¿La cabeza se ajusta a la corona o la corona se ajusta a la cabeza?",
    ["In becoming the personification of winter, have I ceased to be a young ice sprite named Lumi?"] = "Al convertirme en la personificación del invierno, ¿he dejado de ser un joven duende del hielo llamado Lumi?",
    ["Ultimately, the question is irrelevant. I am what I am, and I shall remain irrevocably transformed, whether by the weight of responsibility or the role I inhabit, until I, too, return to snow or vacate the throne."] = "En última instancia, la pregunta es irrelevante. Soy lo que soy y permaneceré irrevocablemente transformado, ya sea por el peso de la responsabilidad o por el papel que desempeño, hasta que yo también regrese a la nieve o deje el trono.",
    ["What is an ice sprite?"] = "¿Qué es un duende de hielo?",
    ["Ice sprites trace our lineage to the King of Roses and Queen of Snow. Direct descendants are usually potential candidates to perpetuate the monarchy."] = "Los duendes de hielo remontan nuestro linaje al Rey de las Rosas y Queen of Snow. Los descendientes directos suelen ser candidatos potenciales para perpetuar la monarquía.",
    ["Given their political importance, ice sprite princesses and princes are typically not allowed to leave the Land of Snow unless an appeal is granted."] = "Dada su importancia política, a las princesas y príncipes duendes de hielo normalmente no se les permite abandonar la Tierra de la Nieve a menos que se conceda una apelación.",
    ["Ice sprites are mortal, like you humans, but longer-lived."] = "Los duendes de hielo son mortales, como ustedes los humanos, pero viven más tiempo.",
    ["Reductively speaking, we can also play with cold and water."] = "Reductivamente hablando, también podemos jugar con frío y agua.",
    ["You've met the god of balance?"] = "¿Has conocido al dios del equilibrio?",
    ["Well, not personally.<br>But so my father declared (with much conviction) when I ascended the throne at my coronation."] = "Bueno, personalmente no.<br>Pero eso declaró mi padre (con mucha convicción) cuando ascendí al trono en mi coronación.",
    ["I am obligated to perpetuate that declaration.<br>Such beliefs can be comfortably reassuring."] = "Estoy obligado a perpetuar esa declaración.<br>Estas creencias pueden resultar cómodamente tranquilizadoras.",
    ["I have a different question..."] = "Tengo una pregunta diferente...",
    ["What is the Land of Snow?"] = "¿Qué es la Tierra de la Nieve?",
    ["The Land of Snow is where snowmen dance and never melt, celebrating winter all year long."] = "La Tierra de la Nieve es donde los muñecos de nieve bailan y nunca se derriten, celebrando el invierno durante todo el año.",
    ["This land was created aeons ago by Guthix, as part of his balancing of your world."] = "Esta tierra fue creada hace eones por Guthix, como parte de su equilibrio de tu mundo.",
    ["The cold of the Land of Snow counteracts the perpetual heat of its counterpart, the Land of Sunlight, ensuring the correct and comfortable balance of hot and cold in Gielinor."] = "El frío de la Tierra de la Nieve contrarresta el calor perpetuo de su contraparte, la Tierra de la Luz del Sol, asegurando el correcto y confortable equilibrio entre calor y frío en Gielinor.",
    ["Here in the Land of Snow, it is winter all year 'round, with bright clear stars overhead and crisp snow underfoot. To us, there is no 'last Christmas' or 'next Christmas'. It is always Christmas."] = "Aquí, en la Tierra de la Nieve, es invierno todo el año, con estrellas brillantes y claras en lo alto y nieve crujiente bajo los pies. Para nosotros no existe la “última Navidad” ni la “próxima Navidad”. Siempre es Navidad.",
    ["This is the realm where winter weather, and the very idea of snow, originates. During winter, your world is aligned to the Land of Snow; close enough to visit, for a short time."] = "Este es el reino donde se origina el clima invernal y la idea misma de la nieve. Durante el invierno, vuestro mundo está alineado con la Tierra de la Nieve; lo suficientemente cerca para visitarlo, por un corto tiempo.",
    ["Every visitor to the Land of Snow, every snowball thrown and snowman made, sends echoes of Christmas cheer through every world."] = "Cada visitante de la Tierra de la Nieve, cada bola de nieve lanzada y cada muñeco de nieve hecho, envía ecos de alegría navideña a todos los mundos.",
    ["Tell me about snow and snow imps."] = "Háblame de la nieve y de los diablillos de nieve.",
    ["When your world and the Land of Snow are close, I send my snow imps to Gielinor to share the gift of snow."] = "Cuando tu mundo y la Tierra de la Nieve están cerca, envío mis diablillos de nieve a Gielinor para compartir el regalo de la nieve.",
    ["The snow my imps bring you has a little of the Land of Snow's magic... amplified by every heart the snow touches."] = "La nieve que te traen mis diablillos tiene un poco de la magia de la Tierra de la Nieve... amplificada por cada corazón que toca la nieve.",
    ["All snow that falls in other worlds is a reflection of the eternal substance of the Land of Snow."] = "Toda la nieve que cae en otros mundos es un reflejo de la sustancia eterna de la Tierra de la Nieve.",
    ["Tell me about snowmen."] = "Háblame de muñecos de nieve.",
    ["Snowmen are the eternal substance of snow, shaped into the form of man. When you build a snowman, you form an instance of a snowman in the Land of Snow; a crude and temporary copy. A vessel for an idea."] = "Los muñecos de nieve son la sustancia eterna de la nieve, con la forma del hombre. Cuando construyes un muñeco de nieve, formas un ejemplo de muñeco de nieve en la Tierra de la Nieve; una copia tosca y temporal. Un recipiente para una idea.",
    ["On Gielinor, winter is but a season in your year. When a snowman melts, its essence returns to the Land of Snow."] = "En Gielinor, el invierno no es más que una estación del año. Cuando un muñeco de nieve se derrite, su esencia regresa al País de la Nieve.",
    ["Here, winter never ends. Snow never melts. This joining of form and essence are eternal. So in the Land of Snow, snowmen are immortal."] = "Aquí el invierno nunca termina. La nieve nunca se derrite. Esta unión de forma y esencia es eterna. Por eso, en el País de la Nieve, los muñecos de nieve son inmortales.",
    ["land-of-snow"] = "tierra-de-nieve",
    ["Traditionally, the Land of Snow's midwinter celebration features a snowman tournament."] = "Tradicionalmente, la celebración de pleno invierno en la Tierra de la Nieve incluye un torneo de muñecos de nieve.",
    ["A great snow tournament, where immortal snow warriors, snow rangers and snow mages battle to see which is best."] = "Un gran torneo de nieve, donde guerreros de nieve inmortales, guardabosques de nieve y magos de nieve luchan para ver cuál es mejor.",
    ["Since each style has counter-balanced advantage against and weakness to another, the whole arrangement honours Guthix."] = "Dado que cada estilo tiene una ventaja y una debilidad contrarrestadas frente a otro, todo el arreglo honra a Guthix.",
    ["Happy Christmas, your majesty."] = "Feliz Navidad, majestad.",
    ["Happy Christmas, noble visitor."] = "Feliz Navidad, noble visitante.",
    ["Hmm? Oh, pardon me, human. I was tracking the movements of warbands out in the Wilderness."] = "¿Mmm? Oh, perdóname, humano. Estaba siguiendo los movimientos de las bandas de guerra en el Wilderness.",
    ["What would you like to ask?"] = "¿Qué te gustaría preguntar?",
    ["Warbands? What do you mean?"] = "¿Bandas de guerra? ¿Qué quieres decir?",
    ["Warbands are gathering under the banners of the pretender gods, looting and hoarding, and gathering like- minded brigands to their cause."] = "Las bandas de guerreros se están reuniendo bajo los estandartes de los dioses pretendientes, saqueando y acaparando, y reuniendo bandidos con ideas afines para su causa.",
    ["They are becoming a threat to the balance of this world, and I am sending adventurers to dispatch them."] = "Se están convirtiendo en una amenaza para el equilibrio de este mundo y enviaré aventureros para despacharlos.",
    ["You look pretty tough. Couldn't you deal with them yourself?"] = "Te ves bastante duro. ¿No podrías encargarte de ellos tú mismo?",
    ["In keeping with the teachings of Guthix, I cannot intervene directly. Rather, I seek to influence events by introduction of a balancing force."] = "De acuerdo con las enseñanzas de Guthix, no puedo intervenir directamente. Más bien, busco influir en los acontecimientos mediante la introducción de una fuerza equilibradora.",
    ["I have the Sight, which allows me to cast my gaze into the Wilderness, spotting any warbands that may be gathering."] = "Tengo la Vista, que me permite mirar al Wilderness y detectar cualquier banda de guerra que pueda estar reuniéndose.",
    ["Why are these warbands gathering out in the Wilderness?"] = "¿Por qué estas bandas de guerra se están reuniendo en Wilderness?",
    ["Recently, there seems to have been a shift in the balance. There have always been outlaws bands living in the wild lands to the north. A nuisance at worst, but lately...something has changed."] = "Recientemente, parece haber habido un cambio en la balanza. Siempre ha habido bandas de forajidos viviendo en las tierras salvajes del norte. Una molestia en el peor de los casos, pero últimamente... algo ha cambiado.",
    ["They appear to have found faith."] = "Parecen haber encontrado la fe.",
    ["Faith? Perhaps that's a good thing."] = "¿Fe? Quizás eso sea algo bueno.",
    ["No! Not at all."] = "¡No! De nada.",
    ["Before, they reaved and plundered - yes - but they lacked focus and discipline, and were fettered by infighting."] = "Antes, saqueaban y saqueaban, sí, pero carecían de concentración y disciplina, y estaban encadenados por luchas internas.",
    ["Now they muster in warbands: hoarding resources; training and marshalling greater forces; committing ever- worse banditry under the banners of the pretender gods."] = "Ahora se reúnen en bandas de guerra: acaparan recursos; entrenar y reunir fuerzas mayores; cometiendo bandidaje cada vez peor bajo los estandartes de los dioses pretendientes.",
    ["Brigands and scoundrels still, but all the more dangerous for their renewed sense of purpose. Men such as these may one day endanger the balance of this world, if left unchecked."] = "Bandidos y sinvergüenzas siguen siendo, pero aún más peligrosos por su renovado sentido de propósito. Hombres como estos podrían algún día poner en peligro el equilibrio de este mundo si no se los controla.",
    ["How can I get involved?"] = "¿Cómo puedo involucrarme?",
    ["Check in with me from time to time. I shall also announce the presence of warband camps in the Wilderness worldwide. Once I have located a warband camp, it may be assailed and the supplies in its tents seized."] = "Consúltame de vez en cuando. También anunciaré la presencia de campamentos de bandas de guerra en Wilderness en todo el mundo. Una vez que haya localizado un campamento de la banda de guerra, puedo ser atacado y confiscar los suministros en sus tiendas.",
    ["So we run in and kill everyone, steal the supplies and bring them back here?"] = "¿Entonces entramos corriendo y matamos a todos, robamos los suministros y los traemos aquí?",
    ["No, no. Killing is not always the best option."] = "No, no. Matar no siempre es la mejor opción.",
    ["Allow me to explain. On arrival, the warband will be on guard and it will not be possible to loot the supply tents. If you can distract them, you'll gain an advantage and - potentially - additional rewards."] = "Permíteme explicarte. A su llegada, la banda estará en guardia y no será posible saquear las tiendas de suministros. Si puedes distraerlos, obtendrás una ventaja y, potencialmente, recompensas adicionales.",
    ["Interesting. Go on."] = "Interesante. Seguir.",
    ["Each camp centres around a summoning beam: an unstable magical node, crudely manipulated by the warband's mages to draw allies to their cause."] = "Cada campamento se centra alrededor de un rayo de invocación: un nodo mágico inestable, crudamente manipulado por los magos de la banda para atraer aliados a su causa.",
    ["If you manage to position yourself somewhere you aren't being seen - but close enough to the beam, with a clear line of sight - it should be a simple matter to shift its alignment."] = "Si logras ubicarte en algún lugar donde no te vean, pero lo suficientemente cerca del haz, con una línea de visión clara, debería ser sencillo cambiar su alineación.",
    ["Once that's done, you can use the beam again, to summon a force less...sympathetic than the warband would hope."] = "Una vez hecho esto, puedes usar el rayo nuevamente para convocar una fuerza menos... comprensiva de lo que la banda esperaría.",
    ["I see...knock the summoning beam out of whack, summon in another warband, and watch the ensuing chaos!"] = "Ya veo... ¡desequilibra el rayo de invocación, convoca a otra banda y observa el caos resultante!",
    ["I prefer to think of it as balance being restored - but yes."] = "Prefiero pensar que se trata de un restablecimiento del equilibrio, pero sí.",
    ["You will receive Prayer experience for shifting the beam, and Summoning experience for successfully summoning aid. After the battle is over, you can loot peacefully."] = "Recibirás experiencia Prayer por cambiar el rayo y experiencia Summoning por convocar ayuda con éxito. Una vez terminada la batalla, podrás saquear pacíficamente.",
    ["So I don't have to fight if I don't feel up to it?"] = "¿Entonces no tengo que pelear si no me siento con ganas?",
    ["No. If you've summoned in reinforcements they can fight for you. When the battle is over, you will be able to loot safely. It'll be quicker if you get involved though!"] = "No. Si has convocado refuerzos, ellos pueden luchar por ti. Cuando termine la batalla, podrás saquear de forma segura. ¡Sin embargo, será más rápido si te involucras!",
    ["Never forget that avarice lurks in the hearts of all men, though, and that this is the Wilderness. Be on guard for treachery from your fellow adventurers!"] = "Sin embargo, nunca olvides que la avaricia acecha en los corazones de todos los hombres y que este es el Wilderness. ¡Esté atento a la traición de sus compañeros aventureros!",
    ["So say I pull this off - I destabilise their beam, converting it to an opposing faction, then use that to summon them in, I just loot whatever I can and bring it back to you?"] = "Entonces, digamos que lo logro: desestabilizo su rayo, convirtiéndolo en una facción opuesta, luego lo uso para convocarlos, ¿simplemente saqueo todo lo que puedo y te lo devuelvo?",
    ["Yes. However, each camp will have different supplies: usually three different types from Herblore, Mining, Smithing, Construction and Farming."] = "Sí. Sin embargo, cada campamento tendrá suministros diferentes: normalmente tres tipos diferentes de Herblore, Mining, Smithing, Construction y Farming.",
    ["You can only take 25 items before the camp is empty, but which 25 items you choose to take is up to you."] = "Solo puedes tomar 25 artículos antes de que el campamento esté vacío, pero los 25 artículos que elijas tomar dependen de ti.",
    ["Be warned, though! Teleportation will not be possible while carrying the items. Even if you can get to the camp quickly, getting out may be a lot more dangerous."] = "¡Pero ten cuidado! La teletransportación no será posible mientras se lleven los artículos. Incluso si puedes llegar al campamento rápidamente, salir puede ser mucho más peligroso.",
    ["Thanks for the information."] = "Gracias por la información.",
    ["I am glad to help. Anything else?"] = "Me alegra poder ayudar. ¿Algo más?",
    ["Ask something else."] = "Pregunta algo más.",
    ["Goodbye."] = "Adiós.",
    ["Peace in balance."] = "Paz en equilibrio.",
    ["Talk about current event."] = "Habla sobre el evento actual.",
    ["I sense no camps in the Wilderness at this time. I feel there is around [hours and minutes] until the next event."] = "No veo ningún campamento en Wilderness en este momento. Siento que queda alrededor de [hours and minutes] hasta el próximo evento.",
    ["I sense no camps in the Wilderness at this time. I sense their forces gathering. They will be with us shortly - prepare yourself!"] = "No siento que no haya campamentos en Wilderness en este momento. Siento que sus fuerzas se reúnen. Estarán con nosotros en breve: ¡prepárate!",
    ["I sense a camp south of the Dark Warriors' Fortress, not far from here."] = "Siento un campamento al sur de la Fortaleza de los Guerreros Oscuros, no lejos de aquí.",
    ["I sense a camp south-east of Red Dragon Isle."] = "Siento un campamento al sureste de Red Dragon Isle.",
    ["I sense a camp east of the Lava Maze."] = "Siento un campamento al este del Laberinto de Lava.",
    ["I do not sense the presence of the summoning beam. The ritual must have failed. Be careful when you head up there."] = "No siento la presencia del rayo de invocación. El ritual debió haber fracasado. Ten cuidado cuando subas allí.",
    ["I sense that the summoning beam is still active. If you make it up to the camp alive in a timely fashion, I'm sure you'll be able to summon in a balancing force."] = "Siento que el rayo de invocación todavía está activo. Si llegas vivo al campamento a tiempo, estoy seguro de que podrás convocar una fuerza de equilibrio.",
    ["Ahh...I sense victory. Reinforcements have already been sent to the camp."] = "Ahh... Siento la victoria. Ya se han enviado refuerzos al campo.",
    ["Anything else I should know?"] = "¿Algo más que deba saber?",
    ["I see figures moving in the camp, so be wary should you choose to assault their position. However, hope of victory is still with us."] = "Veo figuras moviéndose en el campamento, así que ten cuidado si decides atacar su posición. Sin embargo, la esperanza de la victoria todavía está con nosotros.",
    ["I sense that the battle is over. The loot is safe for the taking. Well...as safe as it can be, in the Wilderness."] = "Siento que la batalla ha terminado. El botín está a salvo para tomarlo. Bueno... lo más seguro posible, en el Wilderness.",
    ["Talk about rewards."] = "Habla de recompensas.",
    ["Talk about rewards"] = "hablar de recompensas",
    ["Tell me about rewards."] = "Cuéntame sobre las recompensas.",
    ["I sense turmoil and strife on the horizon, and it would behove us all to seek a balance of powers."] = "Siento agitación y conflictos en el horizonte, y nos correspondería a todos buscar un equilibrio de poderes.",
    ["If you find the camps I sense and bring me back the materials they are hoarding, I shall reward you greatly."] = "Si encuentras los campamentos que siento y me traes los materiales que están acumulando, te recompensaré enormemente.",
    ["And I can find these rewards in the Wilderness?"] = "¿Y puedo encontrar estas recompensas en Wilderness?",
    ["Correct. I can sense the camps, but cannot intervene directly. If you are willing to do so in my place, just return here with the spoils should you make it out alive."] = "Correcto. Puedo sentir los campos, pero no puedo intervenir directamente. Si estás dispuesto a hacerlo en mi lugar, regresa aquí con el botín si logras salir con vida.",
    ["I'd like to toggle my rewards."] = "Me gustaría alternar mis recompensas.",
    ["When I defeat a player carrying supplies in the wilderness, I'd like to receive coins as a reward."] = "Cuando derrote a un jugador que lleva suministros en wilderness, me gustaría recibir coins como recompensa.",
    ["Certainly Player. Speak to me again should you wish to change this."] = "Ciertamente Player. Hable conmigo nuevamente si desea cambiar esto.",
    ["When I defeat a player carrying supplies in the wilderness, I'd like to receive their supplies as a reward."] = "Cuando derrote a un jugador que lleva suministros en wilderness, me gustaría recibir sus suministros como recompensa.",
    ["Task System"] = "Sistema de tareas",
    ["Tell me about the Task System."] = "Cuéntame sobre el sistema de tareas.",
    ["Very well: the Achievement System is a collection of deeds you may wish to complete while adventuring around the world."] = "Muy bien: el Sistema de Logros es una colección de hazañas que quizás desees completar mientras viajas por el mundo.",
    ["You can earn special rewards for completing certain achievements; at the very least, each is worth a cash bounty from Explorer Jack in Lumbridge."] = "Puedes ganar recompensas especiales por completar ciertos logros; como mínimo, cada uno vale una recompensa en efectivo de Explorer Jack en Lumbridge.",
    ["Some also give items that will help complete other achievements, and many count as progress towards the set for the area they're in."] = "Algunos también ofrecen elementos que ayudarán a completar otros logros y muchos cuentan como progreso hacia el conjunto del área en la que se encuentran.",
    ["Tell me about the set reward for this locality."] = "Cuéntame sobre la recompensa establecida para esta localidad.",
    ["For completing the Wilderness set, you are presented with Wilderness sword."] = "Por completar el conjunto Wilderness, se te presenta la espada Wilderness.",
    ["This sword will become increasingly useful with each difficulty level of the set that you complete."] = "Esta espada será cada vez más útil con cada nivel de dificultad del conjunto que completes.",
    ["When you are presented with your rewards, you will be told of their uses."] = "Cuando se le presenten sus recompensas, se le informará sobre sus usos.",
    ["You may also select a set Task (denoted in the main Task System interface by a small shield icon) and choose 'Rewards' to see what rewards a set item provides."] = "También puede seleccionar una tarea determinada (indicada en la interfaz principal del sistema de tareas mediante un pequeño icono de escudo) y elegir 'Recompensas' para ver qué recompensas proporciona un elemento determinado.",
    ["How do I claim these rewards?"] = "¿Cómo reclamo estas recompensas?",
    ["You need to complete all the Tasks in the set of a particular difficulty, then you can claim your reward. Most of the Wilderness set's Tasks are straightforward, although you might find some require quests to be"] = "Debes completar todas las tareas del conjunto de una dificultad particular y luego podrás reclamar tu recompensa. La mayoría de las tareas del conjunto Wilderness son sencillas, aunque es posible que algunas requieran misiones.",
    ["started, if not finished."] = "iniciado, si no terminado.",
    ["To claim the Wilderness set reward, speak to Mr Ex, Mandrith, Kolodion or myself."] = "Para reclamar la recompensa del conjunto Wilderness, habla con Mr Ex, Mandrith, Kolodion o conmigo mismo.",
    ["Sorry, I was just leaving."] = "Lo siento, me estaba yendo.",
    ["Can I claim any rewards from you?"] = "¿Puedo reclamar alguna recompensa de usted?",
    ["You don't have any more rewards to claim!"] = "¡Ya no tienes más recompensas para reclamar!",
    ["I'm afraid you don't have enough inventory space to claim all your rewards. Speak to me again when you have 3 spaces."] = "Me temo que no tienes suficiente espacio en el inventario para reclamar todas tus recompensas. Hablame de nuevo cuando tengas 3 espacios.",
    ["I've completed all the tasks in the hard Wilderness task set."] = "He completado todas las tareas del conjunto de tareas difíciles de Wilderness.",
    ["Well done Player, I've kept some rewards aside for you."] = "Bien hecho Player, he reservado algunas recompensas para ti.",
    ["[You are given some rewards for completing the hard Wilderness task set!]"] = "[¡Recibirás algunas recompensas por completar el difícil conjunto de tareas Wilderness!]",
    ["There you go, looks like that's everything."] = "Ahí lo tienes, parece que eso es todo.",
    ["I lost the Wilderness sword 3 you gave me..."] = "Perdí la espada Wilderness 3 que me diste...",
    ["Lucky for you I have a spare... I'm afraid it's going to cost you 80,000 coins though."] = "Por suerte para ti, tengo uno de repuesto... Aunque me temo que te costará 80.000 coins.",
    ["Reclaim for 80,000 coins?"] = "¿Reclamar 80.000 coins?",
    ["You can not afford that."] = "No puedes permitirte eso.",
    ["But it doesn't look like you have enough money for that. Come back to me when you do."] = "Pero no parece que tengas suficiente dinero para eso. Vuelve conmigo cuando lo hagas.",
    ["[You're handed another Wilderness sword 3.]"] = "[Te entregan otra espada Wilderness 3.]",
    ["Could I buy a spare of the reward?"] = "¿Puedo comprar un repuesto de la recompensa?",
    ["Wilderness sword 1"] = "Wilderness espada 1",
    ["Wilderness sword 1? Yes, but I'm afraid it would cost you 50,000 coins."] = "Wilderness espada 1? Sí, pero me temo que te costaría 50.000 coins.",
    ["Purchase another for 50,000 coins?"] = "¿Comprar otro por 50.000 coins?",
    ["[You're handed another Wilderness sword 1.]"] = "[Te entregan otra espada Wilderness 1.]",
    ["Wilderness sword 2"] = "Wilderness espada 2",
    ["Wilderness sword 2? Yes, but I'm afraid it would cost you 65,000 coins."] = "Wilderness espada 2? Sí, pero me temo que te costaría 65.000 coins.",
    ["Purchase another for 65,000 coins?"] = "¿Comprar otro por 65.000 coins?",
    ["[You're handed another Wilderness sword 2.]"] = "[Te entregan otra espada Wilderness 2.]",
    ["Wilderness sword 3"] = "Wilderness espada 3",
    ["Wilderness sword 3? Yes, but I'm afraid it would cost you 80,000 coins."] = "Wilderness espada 3? Sí, pero me temo que te costaría 80.000 coins.",
    ["Purchase another for 80,000 coins?"] = "¿Comprar otro por 80.000 coins?",
    ["Wilderness sword 4"] = "Wilderness espada 4",
    ["Wilderness sword 4? Yes, but I'm afraid it would cost you 100,000 coins."] = "Wilderness espada 4? Sí, pero me temo que te costaría 100.000 coins.",
    ["Purchase another for 100,000 coins?"] = "¿Comprar otro por 100.000 coins?",
    ["[You're handed another Wilderness sword 4.]"] = "[Te entregan otra espada Wilderness 4.]",
    ["Nothing, actually."] = "En realidad, nada.",
    ["Maintain the balance, Player."] = "Mantener el saldo, Player.",
    ["You don't have any items to hand in."] = "No tienes ningún artículo para entregar.",
    ["Would you like to hand in the reward items?"] = "¿Quieres entregar los artículos de recompensa?",
    ["Yes (for XP)"] = "Sí (para XP)",
    ["You have been awarded [amount] XP in [skill]!"] = "¡Has recibido [amount] XP en [skill]!",
    ["Yes (for [amount]gp)"] = "Sí (para [amount]gp)",
    ["Hand your supplies in for [amount] coins?"] = "¿Entregar sus suministros para [amount] coins?",
    ["Nevermind"] = "No importa",
    ["I see you have some materials on your person already. Would you like me to take them?"] = "Veo que ya tienes algunos materiales contigo. ¿Quieres que los lleve?",
    ["**Quest guide** Ah. Welcome, adventurer. I'm here to tell you all about quests. Let's start by opening the {{colour|blue|Quest List}}."] = "**Quest guide** Ah. Bienvenido, aventurero. Estoy aquí para contarte todo sobre las misiones. Comencemos abriendo el {{colour|blue|Quest List}}.",
    ["**Quest guide** Quests can vary greatly from collecting beads to hunting down dragons. You have to experience the thrill of questing yourself to fully understand. You may find some adventure in the cave under my house."] = "**Quest guide** Las misiones pueden variar mucho, desde recolectar cuentas hasta cazar dragones. Tienes que experimentar la emoción de buscarte a ti mismo para comprenderlo completamente. Quizás encuentres alguna aventura en la cueva debajo de mi casa.",
    ["I was weak once. {{Audio button|Quetzathog - I was weak once.ogg}}"] = "Una vez fui débil. {{Audio button|Quetzathog - I was weak once.ogg}}",
    ["I lacked faith and thought the mwanu lost.{{Audio button|Quetzathog - I lacked faith.ogg}}"] = "Me faltó fe y pensé que el mwanu había perdido.{{Audio button|Quetzathog - I lacked faith.ogg}}",
    ["But Tezcasathla showed me a new path.{{Audio button|Quetzathog - But Tezcasathla showed me a new path.ogg}}"] = "Pero Tezcasathla me mostró un nuevo camino.{{Audio button|Quetzathog - But Tezcasathla showed me a new path.ogg}}",
    ["My world is infested, plagued by the weak and the impure.{{Audio button|Quetzathog - My world is infested.ogg}}"] = "Mi mundo está infestado, plagado de débiles e impuros.{{Audio button|Quetzathog - My world is infested.ogg}}",
    ["But soon I shall return and take back what was stolen.{{Audio button|Quetzathog - But soon I shall return.ogg}}"] = "Pero pronto regresaré y recuperaré lo robado.{{Audio button|Quetzathog - But soon I shall return.ogg}}",
    ["The mwanu will rise again.{{Audio button|Quetzathog - The mwanu will rise again.ogg}}"] = "El mwanu volverá a subir.{{Audio button|Quetzathog - The mwanu will rise again.ogg}}",
    ["Offer me the first of thy master's creations and receive a gift in return."] = "Ofréceme la primera de las creaciones de tu maestro y recibe un regalo a cambio.",
    ["Offer wheel of cheese?"] = "¿Ofrecer rueda de queso?",
    ["Yes, in Raven's name."] = "Sí, en nombre de Raven.",
    ["You can activate this via the 'Titles' tab in the 'Customisations' interface."] = "Puede activar esto a través de la pestaña 'Títulos' en la interfaz 'Personalizaciones'.",
    ["No, weirdo."] = "No, raro.",
    ["Do you really think you can save them? There is an unpleasant metaphor in a scary-sounding place and this is a plot hook."] = "¿De verdad crees que puedes salvarlos? Hay una metáfora desagradable en un lugar que suena aterrador y esto es un gancho argumental.",
    ["Don't let Mod Stu create more puns. The game engine can only handle so many."] = "No dejes que Mod Stu cree más juegos de palabras. El motor del juego sólo puede manejar una cantidad limitada.",
    ["Have you considered killing all your friends? It could be a lot of fun!"] = "¿Has considerado matar a todos tus amigos? ¡Podría ser muy divertido!",
    ["Have you found all of the ravens yet and unlocked all 13 title variants?"] = "¿Ya encontraste a todos los cuervos y desbloqueaste las 13 variantes del título?",
    ["I hear Brassica Prime's voice is utterly melodious."] = "Escuché que la voz de Brassica Prime es absolutamente melodiosa.",
    ["I was thinking of adding a maze here. What do you think?"] = "Estaba pensando en agregar un laberinto aquí. ¿Qué opinas?",
    ["I'm writing a novel, you know. It's all about the best way to eat eyeballs. It's going to be a big hit."] = "Estoy escribiendo una novela, ¿sabes? Se trata de cuál es la mejor manera de comerse los globos oculares. Va a ser un gran éxito.",
    ["LORE LORE LOOOOOOORRRRRE!"] = "LORE LORE ¡LOOOOOOORRRRRE!",
    ["RITE OF PASSAGE!"] = "¡RITO DE PASO!",
    ["Universe Update v-Eh whatever. You all become bees or something. I don't know."] = "Actualización del universo v-Eh, lo que sea. Todos ustedes se convierten en abejas o algo así. No sé.",
}

return dialogues
